const Q = [
  // SET 01
  { id:1,  set:"S01", question:"Which of the following are access rights listed in Article 15 Subject Access?\n\na) The envisaged period for which the personal data will be stored.\nb) Where the personal data are not collected from the data subject, any available information as to their source.\nc) Any recorded criminal activity.\nd) Data transferred to a third country — the right to be informed of the appropriate safeguards.", options:{A:"a, c, and d",B:"a and b",C:"b and d",D:"a, b, and d"}, correct:"D" },
  { id:2,  set:"S01", question:"A group of entrepreneurs think they have spotted a business opportunity to offer training to children from the age of 16 in the gaming market, offering big competition wins and helping to secure future career positions in this lucrative and competitive market. They set up a new company and believed the best way to attract business is to run gaming competitions open to 16-year-olds and above free of charge.\n\nOnce the children have enrolled and enter the competitions, the company plan to start marketing other paid-for services with the promise of winning big money.\n\nThey have been told that under UK law, they can sell to children over the age of 13 without parental consent, but they realise they should look at the Age-appropriate code of practice to cover all bases.\n\nHaving looked at the code, which of the following should this group consider essential practices to enable compliance with the law whilst running a competitive business?\n\na) Not engage in the use of nudge techniques\nb) Geolocation should be switched on by default.\nc) Ensure settings have defaulted to high privacy.\nd) Apply the standards in this code to child users.\ne) When collecting data, give children a simple choice relating to what is collected and retained to cover all the elements the child wishes to activate.", options:{A:"a, b, and d",B:"a, c, and d",C:"b, c and e",D:"c, d and e"}, correct:"B" },
  { id:3,  set:"S01", question:"According to the UK GDPR regime, under which of the following circumstances SHOULD a data protection impact assessment be required?\n\nWhen….\n\na) Systematic processing is based on automated means.\nb) Processing data relating to criminal convictions and offences.\nc) Carrying out an analysis of an individual's use of consumer credit.\nd) Conducting large-scale systematic monitoring of publicly accessible information.", options:{A:"c and d only",B:"a, c and d only",C:"a, and b only",D:"a, b and c only"}, correct:"C" },
  { id:4,  set:"S01", question:"A company wishes to market a special offer to people who have emailed to enquire about opening times. Would this be permissible under ePrivacy Regulations (PEC Regs)?", options:{A:"Yes, because it is covered under the soft-opt-in",B:"Yes, because the person shouldn't have enquired if they didn't expect to receive marketing messages.",C:"No, because there is no consent.",D:"They cannot use the email addresses because they haven't obtained consent, and the soft-opt-in does not cover it."}, correct:"D" },
  { id:5,  set:"S01", question:"Which of the following describes the principle of 'Purpose Limitation' in Article 5 GDPR regimes?\n\na) The controller can only process personal data for specified, explicit, and legitimate purposes.\nb) The Data Subject provides their personal data for a particular purpose.\nc) Not further processed by or on behalf of the controller in a manner that is incompatible with the purpose for which the controller collected the data.\nd) The purpose of personal data processing must be notified to the ICO, and no other processes are accepted.\ne) The Controller can only process personal data for a legitimate purpose.\nf) Article 8A UK GDPR considers where a new purpose of processing is in a manner compatible with the original purpose.", options:{A:"d, e and f only",B:"a, c and f only",C:"a, b and f only",D:"b, d and f only"}, correct:"B" },
  { id:6,  set:"S01", question:"Which of the following are TRUE regarding the UK GDPR recitals?\n\na) Recitals are enforceable under the UK GDPR.\nb) The UK Government recommends utilising the recitals.\nc) Recitals are essential as they are the explanatory notes of the Articles in the EU GDPR.\nd) Infringement of the recitals carries the same maximum financial penalty of 4% of global turnover or £17.5 million, whichever is greater.", options:{A:"a and d",B:"c and d",C:"b and d",D:"b and c"}, correct:"D" },
  { id:7,  set:"S01", question:"Which of the following AI statements are True?\n\na) The goal is to create machines that can think and reason like humans.\nb) Machine learning is studying virtually.\nc) AI risks can be considered in various dimensions such as Technical and Ethical.\nd) Generative AI such as ChatGPT are highly trained chatbots.", options:{A:"a, b, and c",B:"b, c, and d",C:"a, b, and d",D:"a, c, and d"}, correct:"D" },
  { id:8,  set:"S01", question:"If a processor wishes to engage another processor (sub processor), according to Article 28 of UK GDPR, what factors must the processor initiate.\n\na) Only consider a processor who can provide sufficient guarantees to implement appropriate technical and organisational measures.\nb) As a processor-to-processor, there is no requirement to have a binding contract.\nc) If a processor infringes this Regulation by determining the purposes and means of processing, the processor shall be a controller for that processing.\nd) The processor should delete or return all the personal data at the end of the contract only if requested but remains free to continue processing it.\ne) The processor has no statutory obligation of confidentiality.\nf) Where that other processor fails to fulfil its data protection obligations, the initial processor shall remain fully liable to the controller for the performance of that other processor's obligations.", options:{A:"b, c, d and e",B:"a, c, and f",C:"b, d and e",D:"a, b, d and f"}, correct:"B" },
  { id:9,  set:"S01", question:"Controller records of processing activity (ROPA) shall contain which of the following information?\n\na) Full technical and organisational security details\nb) Name, contact details of the Controller and, where applicable Joint Controllers\nc) A detailed list of all retention periods\nd) The categories of recipients to whom personal data have been or will be disclosed, including recipients in third countries.\ne) Categories of data subjects and categories of personal data\nf) Details of any data breach\ng) Names of third countries that personal data are transferred to.", options:{A:"b, d, e and g",B:"a, c, d and f",C:"b, c, d and g",D:"a, b, d and e"}, correct:"A" },
  { id:10, set:"S01", question:"The Privacy and Electronic Communications Regulations (PEC Regs) prohibit unsolicited direct marketing by electronic mail without the individual's consent.\n\nWhich of the following statements explain the exception to this rule?\n\na) The exemption is referred to as the soft-opt-in\nb) Provide a privacy notice explaining clearly that it intends to use those details for marketing purposes.\nc) Where electronic contact details are obtained concerning a negotiation or sale of a product or service, the individual is given the opportunity to refuse further contact.\nd) Where the details are used for direct marketing of similar products or services, the company must clearly state who the controller is and give clear and distinct details to unsubscribe with each marketing message.\ne) It is an offence to sell or offer to sell a marketing list if details were obtained without the individual's consent.\nf) The marketer must get consent from the customer before each new marketing message.", options:{A:"b, c, and d",B:"b, d, e and f",C:"a, c, and d",D:"a, e, and f"}, correct:"C" },
  { id:11, set:"S01", question:"In the following Controller/processor true scenario, who was responsible for the decision to share personal data with the U.S. Treasury (UST)?\n\nThe US Treasury had issued thousands of subpoenas for information to the SWIFT organisation. SWIFT had responded by passing the requested details to the UST.\n\nThe Society for Worldwide Interbank Financial Telecommunication (SWIFT) were the intermediary network for international money transfers working under the instruction of Financial institutions (the controllers). Many of the Board members of SWIFT were from the Financial Institutions and were aware of the subpoenas. SWIFT had no access to the personal data and acted as the processor.\n\nConsidering Article 28 and the processor's responsibilities, what do you believe was the outcome of this case?", options:{A:"SWIFT became the controller as they passed the information to UST.",B:"The Financial institutions were overall responsible and should have had more influence over their processor.",C:"The Financial institutions committed an offence.",D:"A joint responsibility existed, with SWIFT bearing the primary responsibility and the institutions some burden, but both failed to comply with the provisions."}, correct:"D" },
  { id:12, set:"S01", question:"Which of the following is not a listed task of the DPO in Article 39 of the UK GDPR?", options:{A:"To monitor compliance with the policies of the controller or processor concerning the protection of personal data.",B:"Awareness-raising and training of staff involved in processing operations.",C:"To cooperate with the ICO.",D:"To conduct data protection impact assessments."}, correct:"D" },
  { id:13, set:"S01", question:"One of the factors relating to appointing a DPO is 'large scale' processing. Although the UK GDPR does not offer precise numbers about the amount of data processed or the numbers of individuals, recital 91 provides some guidance.\n\nWhich of the following would not be considered as 'large scale'?", options:{A:"Processing by a lawyer of the personal data relating to his clients' criminal convictions and offences.",B:"Processing of patient data in the regular course of business by a hospital.",C:"Processing of real-time geo-location data of customers of an international fast-food chain for statistical purposes by a processor specialised in providing these services.",D:"Processing of data (content, traffic, location) by telephone or internet service providers."}, correct:"A" },
  { id:14, set:"S01", question:"Which of the following are considered essential areas in the security of personal data and data protection by design and default?\n\na) Providing and demonstrating processes and procedures that protect personal data.\nb) Appointing a DPO\nc) Data Minimisation\nd) Adherence to an approved certification or code of conduct\ne) Appropriate lawful condition to process\nf) The use of pseudonymisation as a technical measure\ng) Ensuring the accuracy of personal data", options:{A:"a, b, d and e",B:"a, c, d and f",C:"b, c, e and g",D:"b, e, f and g"}, correct:"B" },
  { id:15, set:"S01", question:"Which of the following is not covered in the Data Protection Code of Practice for surveillance cameras and personal information (CCTV code)?", options:{A:"Automatic number plate recognition (ANPR).",B:"Automated facial recognition technologies to identify individuals.",C:"Relevant authorities under the Protection of Freedoms Act Surveillance Camera Code.",D:"Unmanned aerial systems (UAS)."}, correct:"C" },
  { id:16, set:"S01", question:"The ICO guidance on storage and access technologies (cookies and similar technologies) expects controllers to follow specific requirements; which of the following is not required?", options:{A:"Tell people if cookies are set.",B:"Explain what cookies do and why.",C:"Get the user's consent, which must be actively and clearly given.",D:"Get permission to provide online services at someone else's request."}, correct:"D" },
  { id:17, set:"S01", question:"It is an offence for a person to require another person to provide them with, or give access to, a relevant record (often referred to as enforced subject access) Section 184 DPA'18. The relevant records are health records, records of a conviction or caution and records relating to statutory functions.\n\nWhich of the following statements best describes the details of this offence?", options:{A:"The offence relates to preventing subject access requests for background checks.",B:"It creates the offence of requiring relevant records as a requirement for employment.",C:"Organisations are expected to run the necessary background checks without compelling people to obtain and disclose their personal data.",D:"It covers all of the above statements concerning recruitment, continued employment, or a contract for service provision."}, correct:"D" },
  { id:18, set:"S01", question:"A large corporation whose headquarters are based in London wishes to transfer personal data internally within the global corporate group; it has two options in the UK and chooses to set up an agreement approved by the Commissioner using an addendum linking it to the EU process.\n\nWhat is this process called?", options:{A:"International data transfer agreement (IDTA).",B:"Binding corporate rules (BCR).",C:"Appropriate safeguards.",D:"Adequacy regulations."}, correct:"B" },
  { id:19, set:"S01", question:"A controller may be excluded from supplying information under Article 14 (1-4), where the data was collected from a source other than the data subject and providing it would prove impossible or involve a disproportionate effort.\n\nWhich of the following is not an actual example of this exemption?", options:{A:"The processing for archiving purposes in the public interest.",B:"Obtaining or disclosure is expressly required by law or must by law remain secret.",C:"The obligations would be likely to render impossible or seriously impair the achievement of the objectives of that processing.",D:"It would cause an unnecessary burden on the organisation."}, correct:"D" },
  { id:20, set:"S01", question:"Further processing in Article 13(3) and Article 14(4), where the processing is for purposes other than those it was initially collected for, should only be allowed in limited circumstances [Article 8A UK GDPR and recital 50 clarify this].\n\nWhich of the following is not one of those circumstances?", options:{A:"The processing is compatible with the original purposes.",B:"The legitimate interests of the controller Article 6(1)(f).",C:"Consent or requirement of law.",D:"UK law has specified that further processing should be classed as compatible and lawful."}, correct:"B" },
  { id:21, set:"S01", question:"Which of the following is not likely to infringe on a person's right to respect for a private and family life under Article 8 of the European Convention on Human Rights and Fundamental Freedoms (ECHR)?", options:{A:"Correspondence being intercepted by a private detective.",B:"Press publishing photographs of a person at a private wedding with no prior consent.",C:"Voicemails being listened to by journalists without consent.",D:"A sports professional being shown on TV performing at a tournament."}, correct:"D" },
  { id:22, set:"S01", question:"Which of the following statements are correct regarding the effect of the UK's exit from the EU (\"Brexit\") on data protection law in the UK?\n\na) The UK is no longer bound by EU GDPR.\nb) The UK is bound by US federal privacy laws.\nc) The UK no longer has a data protection law.\nd) The UK has been granted adequacy status by the European Commission.", options:{A:"A & D",B:"A, C & D",C:"B & D",D:"A, B, C & D"}, correct:"A" },
  { id:23, set:"S01", question:"When is a company not required to comply with the EU GDPR?", options:{A:"It is based inside the EU but does not send direct marketing to its customers.",B:"It is based outside the EU and does not target customers within the EEA.",C:"It is based in the EU but does not store personal data.",D:"It targets customers globally and has clear terms of service."}, correct:"B" },
  { id:24, set:"S01", question:"Which of the following correctly defines Pseudonymisation?", options:{A:"The processing of personal data in such a manner that the personal data can no longer be attributed to a specific data subject without the use of additional information.",B:"Information which does not relate to an identified or identifiable natural person or to personal data.",C:"Any operation, or set of operations, that is performed on personal data, or on sets of personal data by automated means.",D:"Any form of automated processing of personal data consisting of the use of personal data to evaluate certain personal aspects relating to a natural person."}, correct:"A" },
  { id:25, set:"S01", question:"Which of the following statements best describes the requirement for maintaining accuracy (Article 5(1)(d))?", options:{A:"Data should be adequate, relevant, and limited to what is necessary in relation to the purposes for which they are processed.",B:"Third parties' opinions regarding a data subject should never be recorded as they are objective and may be inaccurate.",C:"If a company takes action against a customer for non-payment that was later found to be an error on the company's part, no record of the error should be kept on the customer's file.",D:"A company should accurately record the source of personal data as well as taking every reasonable step to ensure incorrect data are rectified or erased without delay."}, correct:"D" },
  { id:26, set:"S01", question:"A company has sold tickets to an event and want to contact customers to inform them of a change in the timing of the event.\n\nWhat is the most likely lawful basis for the following processing?", options:{A:"Consent.",B:"Legitimate Interests.",C:"Contract.",D:"Public Interest Task."}, correct:"C" },
  { id:27, set:"S01", question:"You are the newly appointed Data Protection Officer (DPO) for an innovative marketing company. The company has developed a new product which will be installed in shopping centres. A digital screen is placed at the entrance of the centre. A camera scans the customers as they enter the building, and an artificial intelligence (AI) solution analyses the footage in real-time. The footage is stored and used to further train the AI solution.\n\nThe AI solution identifies customers meeting certain criteria and presents bespoke advertisements based on their profiles. For example, if a customer using a wheelchair enters, the screen will display an advertisement for a mobility retail store.\n\nThe screen will be accompanied by a privacy notice at the entrance of the centre, which explains the technology and informs customers that they should not enter if they do not wish to be recorded.\n\nThe previous DPO advised the company that this would involve the processing of special category data and the company can rely on the Article 9 condition of \"manifestly made public\" by the data subject. You have been asked to assess this advice and make a recommendation to the company.\n\nWhich of the following statements is most appropriate in respect of the previous DPO's advice to the company?", options:{A:"The previous DPO was incorrect because the solution is not processing special category data.",B:"The previous DPO was incorrect because the \"manifestly made public\" condition requires the data subjects to have made a deliberate effort to make the information public.",C:"The previous DPO was correct because the information will be in the public domain and available to anyone who observes the data subject.",D:"The previous DPO was correct because the data subjects have made a choice to allow themselves to be recorded."}, correct:"B" },
  { id:28, set:"S01", question:"Which of the following correctly describes the accountability and data governance obligation?", options:{A:"Controllers are responsible for ensuring compliance in all processing activities carried out by themselves and any processors they appoint.",B:"Controllers are responsible for their own processing activities only.",C:"Processors act only on the instructions of controllers and have no accountability for the compliance of that processing.",D:"All processors and controllers have equal accountability for their own, and each other's compliance."}, correct:"A" },
  { id:29, set:"S01", question:"In which of the following circumstances would a Data Protection Impact Assessment (DPIA) not be appropriate?", options:{A:"Planning the implementation of a new database.",B:"Determining if a dedicated Data Protection Officer (DPO) is required.",C:"Reviewing a proposed new text messaging (SMS) marketing strategy.",D:"Considering changes to security controls applied to personal data."}, correct:"B" },
  { id:30, set:"S01", question:"Which of the following statements relating to the benefits of Artificial Intelligence (AI) is incorrect?", options:{A:"The benefits of AI systems always outweigh the risks.",B:"AI systems can bring about more efficiency in repetitive tasks, thereby reducing costs.",C:"AI systems can quickly spot patterns in large datasets that would take humans many years.",D:"The benefits of AI systems are NOT always worth the associated risks."}, correct:"A" },
  { id:31, set:"S01", question:"Which of the following best describes the requirements for records of processing?", options:{A:"Organisations with 250 or more employees must document all their processing activities.",B:"Information collected during one-off recruitment campaigns does not need to be recorded if it is not to be stored long-term.",C:"Organisations using the Vital Interests lawful basis are exempt from this requirement.",D:"Organisations with a Data Protection Officer must document all their processing activities."}, correct:"A" },
  { id:32, set:"S01", question:"RecruitMe is an online recruiting platform. They are developing an Artificial Intelligence (AI) system which helps them to filter applications to popular jobs and automatically reject applicants that do not meet the required level. The project manager decides that a Data Protection Impact Assessment (DPIA) will be required prior to deploying this new AI system. As part of this DPIA, RecruitMe wants to consult with relevant stakeholders.\n\nWhich of the following stakeholders would it be appropriate for RecruitMe to consult with?\n\na) Previous or current job applicants that used RecruitMe's platform.\nb) People with lived experience of automatic application rejection.\nc) Independent AI experts.\nd) RecruitMe's Data Protection Officer.", options:{A:"a and b",B:"a and d",C:"a, b, and d",D:"a, b, c, and d"}, correct:"D" },
  { id:33, set:"S01", question:"Which of the following is not a way to adopt a data protection by design and by default approach?", options:{A:"Carry out regular legitimate interest assessments.",B:"Consider the implications of data protection as part of all new system integrations.",C:"Offer strong privacy defaults and user-friendly documentation and controls.",D:"Make data protection an essential component of the core functionality of your processing systems and services."}, correct:"A" },
  { id:34, set:"S01", question:"Which of the following statements regarding the security requirement of Article 32 of the GDPR is incorrect?", options:{A:"Security controls must effectively protect the confidentiality, integrity, and availability of personal data.",B:"Companies must make data protection an essential component of the core functionality of your processing systems and services.",C:"Companies should always employ state of the art security controls to all personal information.",D:"A balanced approach should be taken using frequent risk analysis."}, correct:"C" },
  { id:35, set:"S01", question:"Which of the following statements regarding Data Protection Officers (DPO) is correct?", options:{A:"A DPO must ensure that compliance does not undermine other business objectives.",B:"A DPO is solely responsible for a company's compliance with data protection laws.",C:"A DPO must report directly to the highest level of management.",D:"Companies may appoint multiple DPOs where the processing is large-scale."}, correct:"C" },
  { id:36, set:"S01", question:"A third-party company provides a marketing service to your customers. The third-party sends unconsented marketing content to your customers via email, following instructions from your marketing team.\n\nIn the event of a complaint to the Information Commissioners Office (ICO), which of the following correctly describes the position on accountability?", options:{A:"Both companies have acted unlawfully and are accountable.",B:"The controller is solely accountable for the breach as the processor was acting on their instruction.",C:"The processor is solely responsible as they sent the mails.",D:"Providing a suitable legitimate interest assessment and a Data Protection Impact Assessment (DPIA) are completed, there is no possibility of a complaint being upheld."}, correct:"A" },
  { id:37, set:"S01", question:"A travel agency has designed a booking system in collaboration with an airline and two hotel chains. Each of the companies is able to enter and view customer bookings. The travel agency commissioned and paid for the system to be built. The companies have clear documentation outlining responsibilities, and they have equal input in determining the way the data is collected, stored, and processed.\n\nWhich of the following correctly describes the controller/processor relationship that applies in this scenario?", options:{A:"The airline is the controller as it is required to process special category personal data, the travel agency and hotel chain are processors.",B:"The travel agency is the controller, the airline and hotel chains are processors.",C:"All parties are joint processors, each having liability only for their specific actions.",D:"All parties are joint controllers and are accountable for ensuring compliance is maintained."}, correct:"D" },
  { id:38, set:"S01", question:"You have been asked to review data processing agreements between EG Accounts Ltd, a company providing accounting and payroll services for construction companies and their customer; LPJ Building Ltd.\n\nYou are preparing a list of facts to assist in creating the agreement.\n\nWhich of the following statements is incorrect?", options:{A:"EG Accounts Ltd must only process employee data according to explicit instructions from LPJ Building Ltd.",B:"The processing agreement should clearly state what happens to the data when the contract is ended.",C:"LPJ Building has no liability for the way EG Accounts Ltd processes and stores the data.",D:"In the event of a serious data breach, both companies may be investigated by the ICO."}, correct:"C" },
  { id:39, set:"S01", question:"Which of the following stipulations is not specifically required in a contract between a controller and a processor?", options:{A:"That the processor deletes or returns the personal data at the end of the services.",B:"That the processor makes available all information necessary to demonstrate compliance with the GDPR.",C:"That the processor ensures that all personnel involved in the processing respect confidentiality.",D:"That the processor conducts and provides a Data Protection Impact Assessment (DPIA)."}, correct:"D" },
  { id:40, set:"S01", question:"Under the UK data protection regime, which of the following officeholders is able to declare a third country as providing an adequate level of protection for personal data?", options:{A:"The Information Commissioner's Office (ICO).",B:"Secretary of State for the Department for Science, Innovation and Technology.",C:"Prime Minister.",D:"Secretary of State for Foreign Affairs."}, correct:"B" },
  // SET 02
  { id:41, set:"S02", question:"Under what circumstances is the right to object (GDPR Article 21) an absolute right?", options:{A:"Where the data are being processed for direct marketing.",B:"When the data involved includes special category data.",C:"Where the data is being processed by religious organisations.",D:"When the data includes medical records."}, correct:"A" },
  { id:42, set:"S02", question:"Article 23 allows member states to restrict the scope of the obligations and rights provided for in Articles 12–22 by way of legislation.\n\nHow has the UK made use of this?", options:{A:"The Data Protection Act 2018 permits a data controller to disclose personal data for the prevention or detection of crime or for the apprehension and prosecution of offenders.",B:"Under the existing Computer Misuse Act 1990, Article 23 permits a controller to disclose personal data to authorities for the prevention or detection of crime.",C:"The UK has not made any legislation relating to GDPR Article 23 restrictions.",D:"The Freedom of Information Act 2000 requires controllers to release personal data when it is deemed to be in the public interest."}, correct:"A" },
  { id:43, set:"S02", question:"Which of the following is one of the mandatory factors of Independent Supervisory Authorities (ISAs)?", options:{A:"Each supervisory authority may be subject to financial penalties from their respective governments if they fail to meet their financial targets.",B:"They must be entirely independent bodies, competent, and they must provide other ISAs with mutual assistance.",C:"They must have full jurisdiction over all data protection matters and they must be fully independent.",D:"Supervisory authorities must be granted powers of investigation and arrest, and they must be given sufficient and independent funding by the state."}, correct:"B" },
  { id:44, set:"S02", question:"A German data subject feels their privacy rights under Article 21 of the GDPR have been breached by an international social media company. The company has a data protection representative based in Spain. The data subject submitted a DSR to the company but feels it has not been correctly addressed.\n\nTo which of the following would you advise the data subject to escalate their concern?", options:{A:"The European Data Protection Board (EDPB).",B:"Only the Spanish Data Protection Agency (AEPD).",C:"Only the German ISA.",D:"Either a German ISA, or the Spanish Data Protection Agency (AEPD)."}, correct:"D" },
  { id:45, set:"S02", question:"Which of the following is not a role of the European Data Protection Board?", options:{A:"Provide general guidance to clarify the law.",B:"Advise the European Commission on issues related to the protection of personal data.",C:"Adopt consistency findings in cross-border data protection cases.",D:"Supervising the Independent Supervisory Authority's handling of major cases."}, correct:"D" },
  { id:46, set:"S02", question:"Under which of the following circumstances is it most likely that the Information Commissioner's Office (ICO) would impose a higher tier fine (up to £17.5 million or 4% global turnover)?", options:{A:"A failure to obtain proper consent or soft opt-in before contacting customers for marketing purposes.",B:"Failure to appoint a Data Protection Officer (DPO) where one is required.",C:"Failure to notify customers of a significant compromise of their data.",D:"Failure to implement state of the art security controls to protect all personal data."}, correct:"A" },
  { id:47, set:"S02", question:"You are working in the data protection team of a large company holding multiple databases containing personal data. Your team is responsible for handling personal data breaches.\n\nYou are asked to look at the following cases — which of these does not constitute a personal data breach?", options:{A:"Paper copies of customer postal addresses lost on public transport.",B:"Customer credit card data being illicitly photographed by an employee.",C:"Unconsented emails sent to customers.",D:"Emails sent to customers accidentally containing other customers' email addresses."}, correct:"C" },
  { id:48, set:"S02", question:"You are a Data Protection Officer (DPO) for a supermarket chain. The IT department have alerted you to a potential data breach involving an old marketing database. You have been asked to oversee the investigation and determine if the Information Commissioner's Office (ICO) and data subjects should be informed.\n\nWhich of the following correctly describes how you should determine if the ICO and the data subjects should be notified?", options:{A:"If any database containing personal data has been accessed by an unauthorised person.",B:"If any personal information has been made publicly available, for example on the internet.",C:"Only if the breach is likely to result in a significant risk to the data subjects' rights and freedoms.",D:"If the data subjects are existing customers."}, correct:"C" },
  { id:49, set:"S02", question:"Which of the following describes the proper course of action for a data protection complaint?", options:{A:"A data subject may make a complaint directly to the Information Commissioner's Office (ICO), who is bound to investigate the matter to a suitable extent.",B:"A data subject makes a complaint to the Information Commissioner's Office (ICO), and the ICO then raises an information notice with the controller instructing them to process the complaint accordingly.",C:"A data subject must log a complaint first with the Data Protection Officer (DPO) at a company, who may escalate to the Information Commission's Office (ICO).",D:"A data subject may make a complaint to the Information Commissioner's Office (ICO) after having first submitted a data subject access request to the company they wish to complain about."}, correct:"A" },
  { id:50, set:"S02", question:"In which of the following circumstances may the judicial courts deal with data protection matters?", options:{A:"Issuing enforcement notices.",B:"Appealing a decision of a supervisory authority.",C:"Imposing fines following breaches of compliance.",D:"Ordering searches of company premises."}, correct:"B" },
  { id:51, set:"S02", question:"Which of the following correctly describes the ICO Children's Code?", options:{A:"A data protection code of practice for online services likely to be accessed by children.",B:"A code of practice for ensuring parental consent is in place when processing data of children under 13.",C:"A regulation that sits alongside the GDPR mandating enhanced security controls for children's data.",D:"A framework for developers advising on secure coding for apps likely to be used by children."}, correct:"A" },
  { id:52, set:"S02", question:"Which of the following is an exempt public authority or public body according to section 7 of the Data Protection Act 2018?", options:{A:"Public Health England.",B:"A community council in Wales.",C:"HM Passport Office.",D:"The National Centre for Cyber Security (NCSC)."}, correct:"B" },
  { id:53, set:"S02", question:"Other than when specifically exempt under section 7 of the Data Protection Act, which of the following correctly describes when public authorities are required to appoint a Data Protection Officer (DPO)?", options:{A:"When they employ over 250 employees or conduct large scale processing of personal data.",B:"Under all circumstances.",C:"Always, except if they are a court acting in their judicial capacity.",D:"Only if they conduct large scale processing of personal data, or profiling."}, correct:"C" },
  { id:54, set:"S02", question:"Which of the following statements regarding the restriction for health data in the right of access is incorrect?", options:{A:"It restricts data subjects from making data subject requests regarding health care data.",B:"It restricts companies from disclosing health data in response to a subject access request in certain circumstances.",C:"It does not apply to health professionals.",D:"It does not apply if the information is already known by the data subject."}, correct:"A" },
  { id:55, set:"S02", question:"What is the primary area of data protection that the Privacy and Electronic Communication Regulations (PECR) 2003 cover?", options:{A:"Postal marketing.",B:"All forms of marketing.",C:"Websites and cookies.",D:"All forms of electronic communication."}, correct:"D" },
  { id:56, set:"S02", question:"Which of the following areas are not covered by the Privacy and Electronic Communications Regulations (PECR) 2003?", options:{A:"Email marketing.",B:"Cookies and similar technologies.",C:"Postal marketing.",D:"Withholding telephone numbers."}, correct:"C" },
  { id:57, set:"S02", question:"Which of the following is not best practice when collecting and keeping employment records?", options:{A:"Asking workers to regularly check their personal information to make sure it is accurate and up to date.",B:"Ensuring employees can access each other's occupational health records so they can provide appropriate support.",C:"Reminding workers of where to find up to date privacy information outlining how their data is processed.",D:"Identifying a lawful basis for collecting and using worker's personal information."}, correct:"B" },
  { id:58, set:"S02", question:"Which of the following correctly describes how the use of Closed-Circuit Television (CCTV) is governed by data protection law?", options:{A:"CCTV is subject to the Data Protection Act 2018.",B:"CCTV is exempt from GDPR under the law enforcement exemption.",C:"CCTV is not covered by the Data Protection Act but is subject to the Freedom of Information Act.",D:"CCTV does not constitute personal data and therefore is not covered by data protection legislation."}, correct:"A" },
  { id:59, set:"S02", question:"You are working as a Data Protection Officer (DPO) for a travel company. The marketing team would like to use cookies on the company website to track user activity.\n\nWhich of the following privacy legislation applies?", options:{A:"None; the ePrivacy regulation is still in draft.",B:"Both GDPR and PECR apply.",C:"Only PECR applies to cookies.",D:"GDPR has now superseded PECR which no longer applies."}, correct:"B" },
  { id:60, set:"S02", question:"Which of the following correctly describes how data sharing practices are governed by data protection law?", options:{A:"Data sharing practices are covered in the Data Protection Act 2018, where there is a statutory Code of Practice that provides specific guidance.",B:"Data sharing practices are still subject to the Data Protection Act 1998 until the new statutory Code of Practice is published.",C:"Data sharing practices are covered by the Privacy and Electronic Communications Regulations (PECR) 2003.",D:"Data sharing practices are governed by the Freedom of Information Act (FOIA)."}, correct:"A" },
  // SET 03
  { id:61, set:"S03", question:"Which of the following statements relating to the Human Rights Act is CORRECT?", options:{A:"The right to respect a private home and family life is an absolute right.",B:"The right to freedom of expression is an absolute right.",C:"The state can infringe on a person's rights in certain prescribed circumstances.",D:"The state cannot infringe on a person's rights and an impact assessment is required to ensure this remains the case."}, correct:"C" },
  { id:62, set:"S03", question:"With reference to the definitions contained in the GDPR regimes, what statement BEST describes the type of data used by fingerprint scanning software?", options:{A:"It is genetic data as it recognises the special characteristics of an individual's biology in order to identify a person.",B:"It is biometric data as it processes the physical characteristics of an individual in order to identify a person.",C:"It is biometric data as it processes the behavioural characteristics of an individual in order to identify a person.",D:"It is not genetic data or biometric data as it does not process behavioural characteristics."}, correct:"B" },
  { id:63, set:"S03", question:"A public authority funds mandatory training session(s) for its staff on information security. A database has been set up to record attendance at the scheduled training sessions. As Data Protection Officer, you have been asked to advise on the most appropriate lawful basis for processing.\n\nWhich of the below would be MOST suitable under the circumstances?", options:{A:"It is likely that they should rely on the lawful basis of consent and should ask each member of staff for their consent to use their information in the database.",B:"It is likely that they can rely on the lawful basis of public interest task as they are a public authority.",C:"It is likely that they can rely on the lawful basis of legitimate interests as the authority needs to store details of staff who have been trained as a legitimate interest.",D:"It is likely that they can rely on the lawful basis of contract, as employees are bound by contracts of employment."}, correct:"C" },
  { id:64, set:"S03", question:"Article 5(2) of the GDPR states: \"The controller shall be responsible for, and be able to demonstrate compliance with [the data protection principles]\"\n\nWhich of the following does this refer to?", options:{A:"The Accountability Principle.",B:"Data Protection by Design and Default.",C:"Data Protection Impact Assessments.",D:"Information Audits."}, correct:"A" },
  { id:65, set:"S03", question:"Which of the following is INCORRECT in relation to the purpose of a Data Protection Impact Assessment?", options:{A:"To consider both the likelihood and the severity of any impact on individuals.",B:"To completely eliminate all data protection risks.",C:"To mitigate data protection risks.",D:"To identify data protection risks."}, correct:"B" },
  { id:66, set:"S03", question:"Which of the following items is NOT required to be contained within the record of processing activities as set out in the GDPR?", options:{A:"Details of staff training.",B:"Details of data processing.",C:"Details of the Data Subjects.",D:"The purpose of processing."}, correct:"A" },
  { id:67, set:"S03", question:"Of the following, which does NOT illustrate the privacy by design and default approach?", options:{A:"Ensuring that Data Protection Impact Assessments consider all of the risks from the start of the project.",B:"Ensuring that appropriate technical and organisational measures such as data minimisation or pseudonymisation are put in place.",C:"Ensuring that where consent is withdrawn, another lawful basis can be applied if the processing is to continue.",D:"Using an agreed certification method to provide assurances that appropriate safeguards have been put in place to protect personal data."}, correct:"C" },
  { id:68, set:"S03", question:"Which of the following is NOT an obligation of the processor when processing the Personal Data on behalf of the controller?", options:{A:"Keeping a record of processing activities.",B:"Keeping personal data secure.",C:"Assisting the controller in completing Data Protection Impact Assessments.",D:"Determining the purpose of the processing."}, correct:"D" },
  { id:69, set:"S03", question:"From the following list, what information must be included in a Controller-Processor Agreement as specified by Article 28 GDPR?\n\na) The subject matter and duration of the processing\nb) The nature and purpose of the processing\nc) The type of personal data and categories of data subjects\nd) Details of the processor's staff who will have access to the personal data\ne) Obligations and rights of the controller", options:{A:"a, b, c, and d",B:"a, c, d, and e",C:"a, b, d, and e",D:"a, b, c, and e"}, correct:"D" },
  { id:70, set:"S03", question:"The Schrems II case invalidated the Privacy Shield transfer mechanism between the EU and the USA. Which ONE of the following statements is correct following this decision of the CJEU?", options:{A:"Data transfers can still happen as long as the data is encrypted when processed.",B:"Data transfers can still happen if the DPOs of both entities agree.",C:"Data transfers can still happen if an alternative mechanism is used, such as SCCs or BCRs.",D:"Data transfers cannot go ahead until the European Commission and the US Department of Justice agrees on an alternative mechanism."}, correct:"C" },
  { id:71, set:"S03", question:"A government department processes Personal Data in connection with a legal obligation and relies on the Article 6 legal basis of 'Legal Obligation'. Following a recent subject access request, a member of the public notes that their date of birth is incorrect on the record. They write to the department explaining this and insist that they erase all data held about them in accordance with the right to erasure.\n\nWhat advice is appropriate?", options:{A:"They need not do anything. There is a legal obligation to collect the information, and they do not need to correct the record.",B:"They should erase all records relating to the individual as soon as possible.",C:"They should correct the record and inform the individual that the right to erasure doesn't apply.",D:"They should inform the individual that they would need to formally complain as individual rights do not apply to this information."}, correct:"C" },
  { id:72, set:"S03", question:"Of the following statements, which MOST ACCURATELY describes the role of the Information Commissioner's Office in relation to data protection legislation?", options:{A:"A non-departmental public body that reports directly to the United Kingdom Parliament as an independent regulatory office.",B:"An independent regulatory office established by the European Commission and reporting directly to the European Parliament.",C:"A public body, led by an Information Commissioner, answerable directly to government ministers to create data protection legislation.",D:"A government regulator, answerable only to the Prime Minister of the United Kingdom."}, correct:"A" },
  { id:73, set:"S03", question:"Which of the following responsibilities does the Information Commissioner's Office NOT have?", options:{A:"Enforcing the UK General Data Protection Regulation.",B:"Conducting data protection audits.",C:"Prior consultations of Data Protection Impact Assessments where the risk cannot be mitigated.",D:"Co-operating with other Supervisory Authorities."}, correct:"D" },
  { id:74, set:"S03", question:"Which of the following is most likely NOT to be a personal data breach?", options:{A:"The theft of an attendance register from a school.",B:"The loss of a draft public information leaflet on a train.",C:"Sending blood test results to the wrong address.",D:"The accidental destruction of a patient's medical record."}, correct:"B" },
  { id:75, set:"S03", question:"With reference to the following statement, which of the below endings is INCORRECT?\n\n\"In appropriate circumstances, the Information Commissioner may:\"", options:{A:"Instigate criminal proceedings under data protection legislation.",B:"Instigate criminal proceedings under the Computer Misuse Act.",C:"Establish the liability of a Controller and / or Processor.",D:"Order a Controller to compensate a Data Subject."}, correct:"D" },
  { id:76, set:"S03", question:"Which of the following statements is INCORRECT in relation to the lawful basis for processing when offering online services to children?", options:{A:"To rely on consent for an information society service, a child must be over the age of 13.",B:"A different lawful basis to consent can be relied on.",C:"The parent or guardian must consent on behalf of any child.",D:"In general, if you are relying on consent as a lawful basis, the child must be competent to give their consent."}, correct:"C" },
  { id:77, set:"S03", question:"Which of the following statements in relation to the Public Interest Task lawful basis is INCORRECT?", options:{A:"Can be applied where a task is carried out in the exercise of official authority by a public authority.",B:"Can be applied where a task is carried out in the public interest by a non-public body.",C:"There must be a statutory or common law obligation to undertake the task.",D:"The processing of the information must be necessary."}, correct:"C" },
  { id:78, set:"S03", question:"The following statements relate to the differences between GDPR and PECR.\n\nWhich statement is INCORRECT?", options:{A:"GDPR applies to all marketing using personal data.",B:"PECR relates to marketing by electronic means.",C:"The definition of consent under PECR has been updated by GDPR.",D:"PECR does not apply to business-to-business communications."}, correct:"D" },
  { id:79, set:"S03", question:"What statement BEST describes the ICO's Employment Code of Practice?", options:{A:"It must be followed by employers when complying with data protection legislation.",B:"It helps employers in applying employment law in relation to their employees.",C:"It helps employers comply with data protection legislation and encourages them to adopt good practice.",D:"It is designed to help employees understand their rights in relation to data protection legislation."}, correct:"C" },
  { id:80, set:"S03", question:"Under the GDPR, which of the following statements is INCORRECT in relation to cookies?", options:{A:"A person should be able to withdraw consent to use cookies.",B:"The GDPR applies to the use of any type of cookie.",C:"Implied consent in relation to cookies is insufficient.",D:"Websites must provide an option to opt out of cookies."}, correct:"B" },
  // SET 04
  { id:81, set:"S04", question:"Relating to Article 27, when might a controller or processor need to have a representative within the EU?\n\na) Where they are not based in the EU but offer goods and services to individuals in the EU\nb) Where they are not based in the EU and their processing activities are related to the monitoring of individuals in the EU\nc) Where they are based in the EU and are processing data of individuals not in the EU\nd) Where they are a public body", options:{A:"a and b",B:"c and d",C:"a and c",D:"b and d"}, correct:"A" },
  { id:82, set:"S04", question:"The OECD – Organisation for Economic Co-operation and Development:", options:{A:"Organises cross-border marketing and sales.",B:"Issued guidelines for the protection of privacy and trans-border data flow of personal data.",C:"Only relates to UK companies with cross-border transactions.",D:"Has no relevance to data protection law."}, correct:"B" },
  { id:83, set:"S04", question:"The main establishment within the EU is:", options:{A:"A controller with businesses in more than one member state.",B:"A processor with businesses in more than one member state.",C:"The place of the central administration of a controller or processor with establishments in more than one EU member state.",D:"A place of the central administration of controllers or processors wherever their establishment is based."}, correct:"C" },
  { id:84, set:"S04", question:"Which of the following best describes the one-stop-shop mechanism under EU GDPR?", options:{A:"A shop that sells data protection products.",B:"A single point of contact of a Lead Supervisory Authority for cross-border processing by a controller or processor.",C:"A place a data subject can go to make a complaint.",D:"A place that covers cooperation and mutual assistance."}, correct:"B" },
  { id:85, set:"S04", question:"The Human Rights Act 1998 applies only to the UK.", options:{A:"True",B:"False",C:"True, but only in relation to public authorities.",D:"False, it applies across all EU member states."}, correct:"A" },
  { id:86, set:"S04", question:"Which of the following is NOT an 'identifier' for personal data?", options:{A:"A name.",B:"A cookie or IP address.",C:"A generic work email address.",D:"Cultural or social identity."}, correct:"C" },
  { id:87, set:"S04", question:"Which of the following instruments/conventions/laws are legally binding?\n\na) Convention 108\nb) The Data Protection Directive\nc) The Data Protection Act 2018\nd) ePrivacy Directive", options:{A:"a, c and d",B:"a and c",C:"b and c",D:"c and d"}, correct:"B" },
  { id:88, set:"S04", question:"Which of the following best describes 'Pseudonymisation'?", options:{A:"Processes data so it can no longer be attributed to a specific individual.",B:"It can only identify a specific individual by using additional information.",C:"The additional data is kept secure and in a separate location.",D:"Pseudonymisation requires all of the above."}, correct:"D" },
  { id:89, set:"S04", question:"A 'processor' is an individual or legal person, public authority, or other body:", options:{A:"That inputs data into a computer.",B:"That works for a data controller.",C:"That makes decisions as to a data subject's creditworthiness.",D:"That processes personal data on behalf of a controller."}, correct:"D" },
  { id:90, set:"S04", question:"Which of the following is not explicitly defined in the GDPR regimes?", options:{A:"Personal data.",B:"Risk.",C:"Third-party.",D:"Pseudonymisation."}, correct:"B" },
  // SET 05
  { id:91, set:"S05", question:"The Data Protection, Privacy, and Electronic Communications (Amendments etc.) (EU Exit) Regulations 2019 amended the Data Protection Act 2018 and other legislation. It merged the requirements of the GDPR to form a data protection framework that would continue to function correctly after the UK left the EU.", options:{A:"True",B:"False",C:"This only applied to public authorities.",D:"This only applied to processors."}, correct:"A" },
  { id:92, set:"S05", question:"Which of the following applies to Article 2 Material Scope of the UK GDPR?", options:{A:"Processing of personal data by an individual in the course of a purely personal or household activity.",B:"Automated or structured processing of personal data, including processing during an activity that fell outside the scope of EU law immediately before exit day.",C:"Processing of personal data by a competent authority for any of the law enforcement purposes.",D:"Processing personal data to which Part 4 of the 2018 Act (intelligence services processing) applies."}, correct:"B" },
  { id:93, set:"S05", question:"Principle 5 states, 'storage limitation, personal data should':", options:{A:"Not be kept for longer than three months.",B:"Be kept for up to 100 years.",C:"Be stored in case it becomes useful to the controller.",D:"Not be kept for longer than is necessary."}, correct:"D" },
  { id:94, set:"S05", question:"To comply with Principle 3 (Article 5(1)(c)) Data Minimisation, data shall be:", options:{A:"Appropriate, relevant, and not excessive.",B:"Adequate, relevant, and limited to what is necessary.",C:"Adequate, representative of what is necessary and not excessive.",D:"Accurate, relevant, and limited to what is necessary."}, correct:"B" },
  { id:95, set:"S05", question:"When would explicit consent be required?", options:{A:"Processing of a child's data.",B:"Processing all personal data.",C:"Processing data that is in the legitimate interests of the controller.",D:"Processing special categories of data."}, correct:"D" },
  { id:96, set:"S05", question:"How can a controller prove compliance with the principles?", options:{A:"By complying with the accountability principle.",B:"By complying with the accessibility principle.",C:"By complying with the authorisation principle.",D:"By complying with the application principle."}, correct:"A" },
  { id:97, set:"S05", question:"Which of the following are Principles?\n\na) Purpose limitation\nb) Storage limitation\nc) Rights of the data subject\nd) Integrity and confidentiality", options:{A:"b, c and d",B:"a, b and d",C:"a and c only",D:"a, b and c"}, correct:"B" },
  { id:98, set:"S05", question:"Special categories of personal data cannot be processed unless:\n\na) The data subject has given explicit consent to the processing of those personal data for one or more specified purposes.\nb) The data subject has deliberately not made it public.\nc) It is in the vital interests of the data subject or another where they are incapable of giving consent.\nd) Another controller has asked for the data.", options:{A:"a and c",B:"b and d",C:"c and d",D:"a and b"}, correct:"A" },
  { id:99, set:"S05", question:"Which of the following Article 9 basis of processing requires a DPA 2018 Schedule 1 condition?\n\na) Vital interests\nb) Substantial public interest\nc) Public interest in public health\nd) Establishment, defence, or exercise of legal claims", options:{A:"b and d",B:"c and d",C:"a and c",D:"b and c"}, correct:"D" },
  // SET 06
  { id:100, set:"S06", question:"When should a Data Protection Impact Assessment be undertaken?", options:{A:"Once a decision has been set in stone.",B:"Once you have procured systems.",C:"When a project is being designed.",D:"Once contracts/agreements have been signed."}, correct:"C" },
  { id:101, set:"S06", question:"Which of the following is NOT a requirement to be included in a DPIA?", options:{A:"The description of the predicted processing operations and the purposes of the processing, including, if applicable, the legitimate interest pursued by the controller.",B:"An assessment of the necessity and proportionality of the processing operations concerning the purposes.",C:"Whether the costs involved exempt the carrying out of a DPIA.",D:"The measures put in place to address the risks, including safeguards, security measures and mechanisms to ensure the protection of personal data and to demonstrate compliance with this Regulation."}, correct:"C" },
  { id:102, set:"S06", question:"Which statement relating to Prior consultation Article 36 with the supervisory authority/Commissioner is INCORRECT?", options:{A:"Required where DPIA indicates the processing would result in a high risk in the absence of measures taken by the controller to mitigate the risk.",B:"The controller is not required to provide further information to the Supervisory Authority/Commissioner.",C:"The Supervisory Authority/Commissioner will have 8-weeks to provide written advice to the controller.",D:"This timeframe can be extended by a further six weeks."}, correct:"B" },
  { id:103, set:"S06", question:"Of the following, which does NOT illustrate the privacy by design and default approach?", options:{A:"Ensuring that Data Protection Impact Assessments consider all of the risks from the start of the project.",B:"Ensuring appropriate technical and organisational measures such as data minimisation or pseudonymisation are implemented.",C:"Ensuring that where consent is withdrawn, another lawful basis can be applied if the processing is to continue.",D:"Using an agreed certification method to ensure that appropriate safeguards have been put in place to protect personal data."}, correct:"C" },
  { id:104, set:"S06", question:"Which of the following is NOT a required record of processing activities (ROPA)?", options:{A:"The purpose of the processing.",B:"A description of the categories of data subjects and the categories of the personal data.",C:"Where possible, the envisaged time limits for erasure of the different categories of data.",D:"Testing, assessing, and evaluating the technical and organisational measures for ensuring the security of the processing."}, correct:"D" },
  { id:105, set:"S06", question:"Controllers and Processors must maintain a record of processing activities (ROPA) under their responsibilities. Which of the following statements is INCORRECT in respect of Article 30?", options:{A:"The Controller or processor has more than 250 staff.",B:"The processor must maintain records of processing activities carried out on behalf of the controller.",C:"Only relates to companies whose staff are based in third countries.",D:"No minimum staff numbers where the processing is likely to result in a risk to the rights and freedoms of data subjects."}, correct:"C" },
  { id:106, set:"S06", question:"Controllers and the processors shall implement appropriate technical and organisational measures to ensure a level of security appropriate to the risk, including, amongst other things, as applicable:\n\na) The pseudonymisation and encryption of personal data.\nb) The ability to ensure the ongoing confidentiality, integrity, availability and resilience of processing systems and services.\nc) The ability to restore the availability and access to personal data in a timely manner in the event of a physical or technical incident.\nd) A process for regularly testing, assessing, and evaluating the effectiveness of technical and organisational measures for ensuring the security of the processing.\ne) A process to profile and screen all personnel involved in securing personal data.", options:{A:"a, b, d and e",B:"b, c, d and e",C:"a, c and d",D:"a, b, c and d"}, correct:"D" },
  // SET 07
  { id:107, set:"S07", question:"Which of the following would NOT be considered a security measure?", options:{A:"Security awareness training.",B:"ISO 9001.",C:"Data protection impact assessments.",D:"Pseudonymisation."}, correct:"B" },
  { id:108, set:"S07", question:"Which of the following is NOT a position of DPO as listed in Article 38?", options:{A:"The controller and the processor need to involve the DPO fully and at the earliest point.",B:"The controller or processor must provide the necessary funding and resources to support the DPO in performing their tasks.",C:"The data protection officer reports directly to their manager of the controller or the processor.",D:"The DPO will be bound by confidentiality concerning the performance of their tasks."}, correct:"C" },
  { id:109, set:"S07", question:"Which of the following Data Protection Officer (DPO) statements is true?", options:{A:"All companies subject to enforcement require a DPO.",B:"Public authorities and public bodies require a DPO unless specifically exempt by law.",C:"Only marketing companies require a DPO.",D:"The ICO will issue a list of sectors that will require a DPO."}, correct:"B" },
  { id:110, set:"S07", question:"As the data protection officer, advise the best action your CEO should take following a breach of security by your private sector organisation involving children's data likely to cause serious risk.", options:{A:"You have 72 hours from becoming aware of the breach to notify the ICO.",B:"You must report any breach if it involves children's data within a month.",C:"You only need to report some breaches involving the loss of personal data.",D:"It is a breach of your security policy to notify anyone, including the ICO."}, correct:"A" },
  { id:111, set:"S07", question:"Under the GDPR regimes and Data Protection Act, a Processor has:", options:{A:"A statutory requirement to offer a level of security equal to those imposed on a Controller.",B:"No statutory obligations, only contractual.",C:"A statutory duty to provide data subjects with subject access.",D:"A statutory duty to share data with other processors."}, correct:"A" },
  { id:112, set:"S07", question:"If a controller engages a processor, he should ensure that the processor:", options:{A:"Can implement appropriate security measures to meet the requirements of the Regulations.",B:"Has carried out credit checks on all employees.",C:"Has installed a firewall.",D:"Has carried out work for the Controller in the past."}, correct:"A" },
  { id:113, set:"S07", question:"From the following list, what information must be included in a Controller-Processor Agreement as specified by Article 28 GDPR?\n\na) The subject matter and duration of the processing\nb) The nature and purpose of the processing\nc) The type of personal data and categories of data subjects\nd) Details of the processor's staff who will have access to the personal data\ne) Obligations and rights of the controller", options:{A:"a, b, c, and d",B:"a, c, d, and e",C:"a, b, d, and e",D:"a, b, c, and e"}, correct:"D" },
  // SET 08
  { id:114, set:"S08", question:"A UK bank has moved its call centre operations to a company in India. They do not inform customers as customers still dial a UK number. One customer has written to the bank to complain, claiming that his personal data is being processed in India without his consent and without him being advised of this.\n\nWhich of the following statements would be correct?\n\na) The processing is lawful as it is necessary for the performance of a contract.\nb) James has the right to object to the Controller processing using '6(1)(b) Performance of a contract.\nc) A controller is not required to include details of the safeguards for any transfers to 3rd countries under Articles 13 & 14.\nd) The bank would require an International Data Transfer Agreement/Addendum or another safeguard to process in a 3rd country.\ne) The relationship between the Bank and the Indian call centre is Controller and Processor.", options:{A:"a, b and c",B:"a, b and e",C:"a, d and e",D:"a, c and d"}, correct:"C" },
  { id:115, set:"S08", question:"The controller or processor may transfer personal data where the organisation receiving the personal data has provided adequate safeguards; which of the following is NOT an adequate safeguard?", options:{A:"Binding corporate rules.",B:"Standard data protection clauses in the form of template transfer clauses adopted by a supervisory authority and approved by the commission.",C:"A long-standing relationship between the organisations concerned.",D:"Certification under an approved certification mechanism."}, correct:"C" },
  { id:116, set:"S08", question:"Which of the following are Derogations to permit 3rd country transfers?\n\na) Transfer is necessary for the performance of a contract.\nb) For important reasons of public interest.\nc) Where the UK has a good relationship with the country the data is being sent to.\nd) Where the transfer is being made from a public register.", options:{A:"a, b and c",B:"a, c and d",C:"a, b and d",D:"b, c and d"}, correct:"C" },
  { id:117, set:"S08", question:"BCRs are agreements governing transfers made between organisations within a corporate group; The competent supervisory authority under EU GDPR or the ICO under UK GDPR shall approve binding corporate rules.", options:{A:"True",B:"False",C:"True, but only for EU-based organisations.",D:"False, only the EDPB can approve BCRs."}, correct:"A" },
  { id:118, set:"S08", question:"Under what circumstances can a data subject enforce their right to restrict the processing of personal data?", options:{A:"When the processing has been carried out by automated means.",B:"Where the processing has been collected concerning the offer of information society services.",C:"Where the data subject contests the accuracy of the personal data.",D:"Where the processing is for direct marketing."}, correct:"C" },
  { id:119, set:"S08", question:"When a controller obtains personal data from a third party (Article 14 (1) & (2)), what information may be provided to the data subject?\n\na) The period for which the personal data will be stored, or the criteria used to determine that period.\nb) The right to lodge a complaint with the ICO.\nc) The source from which the personal data originated and, if applicable, whether it came from publicly accessible sources.\nd) The recipients of the personal data (if any).", options:{A:"a, b and c",B:"b, c and d",C:"a, c and d",D:"a, b, c and d"}, correct:"D" },
  // SET 09
  { id:120, set:"S09", question:"Which of the following are data subject rights listed in the GDPR regimes?\n\na) The right to object\nb) The right to compensation\nc) The right of access\nd) The right to be informed.", options:{A:"a, b and d",B:"a, c and d",C:"b, c and d",D:"a, b and c"}, correct:"B" },
  { id:121, set:"S09", question:"To ensure that profiling and automated individual decision-making are not used in ways that have an unjustified impact on an individual's rights, which of the following provisions would apply?\n\na) Specified legal basis for processing.\nb) Inform the ICO of the planned processing.\nc) Greater accountability obligations.\nd) Rights to oppose profiling for marketing purposes.", options:{A:"b, c and d",B:"a, b and c",C:"a, c and d",D:"a, b and d"}, correct:"C" },
  { id:122, set:"S09", question:"Which of the following are requirements of Data Portability?\n\na) All personal data collected or produced fall within data portability.\nb) The Controller can send personal data provided by the data subject at their request to another controller.\nc) The data will be in a structured, machine-readable, commonly used format.\nd) Processing is based on consent or as part of a contract.", options:{A:"b, c and d",B:"a, b and d",C:"a, c and d",D:"b and c only"}, correct:"A" },
  { id:123, set:"S09", question:"What information would be required to be made available to a 3rd party under a Privacy notice by Article 14?\n\na) The purpose of the processing\nb) Any processing for archiving that is in the public interest.\nc) Statistical information.\nd) Information where the processing is required by law.", options:{A:"The purpose of the processing.",B:"Any processing for archiving that is in the public interest.",C:"Statistical information.",D:"Information where the processing is required by law."}, correct:"A" },
  { id:124, set:"S09", question:"Which of the following is NOT a requirement of access concerning Article 15?", options:{A:"The purpose of the processing.",B:"The right to lodge a complaint with the ICO/Supervisory Authority.",C:"Out of working hours, contact point.",D:"The envisaged period for which the personal data will be stored."}, correct:"C" },
  { id:125, set:"S09", question:"A data subject has the right to be forgotten; in which of the following circumstances can this right be overridden?\n\na) Freedom of expression\nb) Public interest in public health.\nc) In the legitimate interest of the controller.\nd) To establish, exercise, or defend legal claims.", options:{A:"b, c and d",B:"a, b and d",C:"a, c and d",D:"a, b and c"}, correct:"B" },
  // SET 10
  { id:126, set:"S10", question:"The 'special purposes' in the UK, relate to:", options:{A:"Journalism, academic, artistic, and literary purposes.",B:"Personal data collated for genetic research.",C:"Personal data contained in educational records.",D:"Information relating to individuals employed by the security services."}, correct:"A" },
  { id:127, set:"S10", question:"Which of the following may allow an exemption to apply to fair processing?", options:{A:"Quality and monitoring purposes.",B:"Profiling.",C:"Testing and internal systems.",D:"Disclosure to assist a police investigation."}, correct:"D" },
  { id:128, set:"S10", question:"A controller may be able to use an exemption to withhold personal access to data relating to negotiations in which circumstances?", options:{A:"Regarding pay conditions and prospects.",B:"Because it is on a need-to-know basis, and you don't need to know.",C:"Because the exemption is there to be used.",D:"To give controllers a free hand to do whatever they like."}, correct:"A" },
  { id:129, set:"S10", question:"Which of the following statements are true?\n\na) An exemption may allow controllers to withhold personal data.\nb) An exemption enables controllers to release personal data under the law.\nc) An exemption may be used to make personal data public.\nd) An exemption allows controllers to process data where no lawful condition applies.", options:{A:"b, c and d",B:"a, b and c",C:"a, b and d",D:"a, c and d"}, correct:"B" },
  { id:130, set:"S10", question:"Which of the following are exemptions listed in the Data Protection Act '18?\n\na) Where the processing is for purely personal purposes\nb) The activities of the courts and other judicial authorities\nc) The processing of personal data which concerns legal persons.\nd) Confidential references", options:{A:"b and c",B:"a and b",C:"b and d",D:"c and d"}, correct:"C" },
  // SET 11
  { id:131, set:"S11", question:"Which of the following would fall outside the scope of the Data Sharing Code of Practice 2018?", options:{A:"Data pooling.",B:"The disclosure of data from one controller to another controller.",C:"The disclosure of data from a controller to a processor.",D:"Ad hoc or one-off disclosures of data."}, correct:"C" },
  { id:132, set:"S11", question:"What is the maximum tenure of the Information Commissioner?", options:{A:"5 years",B:"7 years",C:"10 years",D:"Life"}, correct:"B" },
  { id:133, set:"S11", question:"A private citizen has a CCTV camera on his house; he believes he is exempt from data protection; which of the following must be true for him to be correct?", options:{A:"He only uses CCTV in the evenings.",B:"He only shares the data with the police.",C:"He never publishes the data on the internet.",D:"He only captures data on his property."}, correct:"D" },
  { id:134, set:"S11", question:"Which of the following is a criminal offence under section 170, Unlawful obtaining etc.?", options:{A:"A nurse accidentally leaves personal data on a train.",B:"Obtaining data from an employer's system to process as part of the job role.",C:"Obtaining data from an employer's system without consent, knowing you shouldn't.",D:"Passing data to a law enforcement officer for the prevention of crime using an exemption."}, correct:"C" },
  { id:135, set:"S11", question:"Which information should be supplied to the ICO following a data breach likely to risk the rights and freedoms of natural persons?\n\na) The nature of the personal data breach\nb) The categories and names of all data subjects concerned.\nc) The categories and approximate numbers of records concerned.\nd) Contact details of the DPO\ne) Details of any members of staff involved in the breach.", options:{A:"b, c, and e",B:"a, b and d",C:"b, d and e",D:"a, c and d"}, correct:"D" },
  // SET 11 (continued — Q136–139)
  { id:136, set:"S11", question:"Which of the following are the Investigative powers of the ICO?\n\na) Carrying out data protection audits\nb) Notifying a controller or processor of an alleged infringement of GDPR\nc) To order the controller or processor to comply with the data subject's right of access.\nd) Obtain from a controller or processor access to all required personal data necessary for the performance of the ICO's tasks.", options:{A:"a, b and d",B:"a, b and c",C:"b, c and d",D:"a, c and d"}, correct:"A" },
  { id:137, set:"S11", question:"Which of the following has no statutory power of enforcement?", options:{A:"Information notice.",B:"Not complying with a statutory code of practice.",C:"Assessment notice.",D:"Enforcement notice."}, correct:"B" },
  { id:138, set:"S11", question:"Which of the following are recordable offences?\n\na) Making false statements in response to information notice\nb) Non-compliance with an information notice.\nc) Unlawful obtaining of personal data\nd) Releasing special category data by forgetting it and leaving it on a train", options:{A:"a, b and d",B:"a and b only",C:"b, c and d",D:"a and c only"}, correct:"D" },
  { id:139, set:"S11", question:"Which of the following are statutory codes of practice?\n\na) Data sharing\nb) Age-appropriate design\nc) Guide to GDPR\nd) Data protection and journalism", options:{A:"b, c and d",B:"a, b and c",C:"a, b and d",D:"a, c and d"}, correct:"C" },
  // SET 12
  { id:140, set:"S12", question:"What actions should you take following a call complaining that the caller's personal data is being processed for direct marketing by your organisation?", options:{A:"The controller must stop the marketing immediately upon receiving a notification to stop from the data subject.",B:"The controller only needs to stop the direct marketing the complaint relates to.",C:"The controller is exempt due to there being the lawful condition of legitimate interests of the controller.",D:"The data subject must prove that the marketing is causing distress."}, correct:"A" },
  { id:141, set:"S12", question:"Which of the following does PECR NOT directly provide rulings on?", options:{A:"Keeping communications secure.",B:"Marketing mailshots.",C:"Cookies and similar technologies.",D:"Marketing by phone, email, text etc."}, correct:"B" },
  { id:142, set:"S12", question:"Which of the following would be considered advertising or marketing?\n\na) Fundraising\nb) Promoting political parties or candidates\nc) Promoting the goods and services of the organisation\nd) Providing information needed by the individual in the context of the existing relationship", options:{A:"a, b and c",B:"a, b and d",C:"b, c and d",D:"a, c and d"}, correct:"A" },
  { id:143, set:"S12", question:"Which of the following forms of marketing require consent or explicit consent for the lawful basis to process?\n\na) Telephone marketing where the individual has registered with the TPS.\nb) Marketing by email or text.\nc) Where direct marketing is necessary for the performance of a contract with that individual.\nd) Claims management and pension scheme calls.", options:{A:"a, c and d",B:"b, c and d",C:"a, b and c",D:"a, b and d"}, correct:"D" },
  // SET 13
  { id:144, set:"S13", question:"You receive a computerised autodial pre-recorded marketing message you haven't requested. Referred to by the ICO as an automated nuisance call.\n\nConcerning this call, which of the following statements are TRUE?\n\na) These are perfectly legal forms of marketing, so you should use the unsubscribe option if you are not interested in the product.\nb) Calls can be associated with political and telemarketing phone campaigns.\nc) Calls can be used for public-service or emergency announcements.\nd) You will receive these nuisance automated marketing calls if you have consented to any form of general marketing.\ne) In general terms, consent for marketing or live calls would not be enough; the consent must specifically cover automated calls.", options:{A:"a, b, d and e",B:"b, c, and e",C:"c, b, and d",D:"a, d, c and e"}, correct:"B" },
  { id:145, set:"S13", question:"Articles 60 to 63 EU GDPR require the Supervisory Authorities to work together. Which of the following is NOT one of these measures?", options:{A:"Mutual assistance",B:"Criminal liabilities",C:"Joint operations",D:"Consistency measures"}, correct:"B" },
  { id:146, set:"S13", question:"Article 34 states: A breach likely to result in a high risk to the data subject shall be notified by the controller to the subject without undue delay. Which of the following statements are correct?\n\na) Describe in clear and plain language the nature of the personal data breach\nb) Communicate the name and contact details of the data protection officer or another contact point where more information can be obtained\nc) The categories and approximate number of data subjects concerned\nd) Describe the likely consequences of the personal data breach.\ne) The categories and approximate number of records concerned.\nf) Describe the measures taken or proposed to be taken by the controller to address the personal data breach.", options:{A:"a, b, d and f",B:"a, b, c, d, e and f",C:"b, c, e and f",D:"a, b, c and e"}, correct:"A" },
  { id:147, set:"S13", question:"The above question relates to a high risk to the data subject; if the question related to a breach that would result in a risk to the rights and freedoms of a natural person resulting in the requirement to notify the ICO of the breach (Article 33), which of the above statements would be correct?\n\na) Describe in clear and plain language the nature of the personal data breach\nb) Communicate the name and contact details of the data protection officer or another contact point\nc) The categories and approximate number of data subjects concerned\nd) Describe the likely consequences of the personal data breach.\ne) The categories and approximate number of records concerned.\nf) Describe the measures taken or proposed to be taken by the controller to address the personal data breach.", options:{A:"a, b, d and f",B:"a, b, c, d, e and f",C:"b, c, e and f",D:"a, b, c and e"}, correct:"B" },
  { id:148, set:"S13", question:"An Enforcement notice may be given by the Commissioner when satisfied that a person has failed or is failing with any of the four types of failure listed in Section 149 DPA'18. Which of the following is not a documented failure?", options:{A:"Compliance with the Principles",B:"Obligations of the controller and processor",C:"Failure to achieve certification of an approved code of conduct.",D:"A certification body failing to comply with any GDPR provision."}, correct:"C" },
  { id:149, set:"S13", question:"Following a tender process resulting in a better price and service from a new processor, the old processor and their agreement are terminated. In the original agreement, there were specific instructions to return the data and not further process it on termination. However, the processor decided to email all the data subjects whose data they had been processing on behalf of the controller to offer their services directly.\n\nWhich of the following correct statements BEST describe the processors' action in this scenario?", options:{A:"They are in breach of the 1st Principle of processing lawfully, fairly and in a transparent manner.",B:"They have no lawful ground within Article 6(1)(a-f) for further processing of the data now the processor agreement has terminated.",C:"They have committed an offence in DPA'18 Section 170 Unlawful obtaining etc., of personal data; for a person knowingly or recklessly to continue to process the data when no longer legally allowed to process it.",D:"They are in breach of PECR as marketing to the data subjects without consent."}, correct:"C" },
  { id:150, set:"S13", question:"Which of the following list of differing roles is the ICO responsible for?\n\na) Maintain and enforce the Register of over half a million fee payers.\nb) Oversee and enforce Re-use of Public Sector Information Regulations\nc) Create new legislation.\nd) Handle enquiries, written concerns, and complaints\ne) Issue compensation\nf) Oversee the Investigatory Powers (Interception by Businesses etc. for Monitoring and Record-keeping Purposes) Regulation.\ng) Instigate government policies around Information Rights", options:{A:"a, c, d and g",B:"b, e, f and g",C:"a, b, d and f",D:"c, d, e and f"}, correct:"C" },
  { id:151, set:"S13", question:"Brown & Sons Ltd is a company employing just over 1,000 people. They outsource their IT function to Real-Computing Ltd; the accountants are Genius Financing; CleaningFirst are their cleaning service, they use Day-to-Day Personnel for all personnel issues and have outsourced their Occupational Health requirements to Occi-services Ltd. There are also cloud service providers to consider.\n\na) Real-Computing Ltd\nb) Genius Financing LLP\nc) CleanFirst\nd) Day-to-Day Personnel\ne) Occi-Services\nf) Cloud Service Providers\n\nWhich providers would typically be a processor for Brown and Sons and require a Data Processing Agreement?", options:{A:"a, b, c and e",B:"a, d, e and f",C:"b, d, e and f",D:"all"}, correct:"B" },
  { id:152, set:"S13", question:"In the above scenario (Brown & Sons Ltd), which of the companies would or could also determine the purpose and means of the processing and therefore be a joint controller or even a controller in some circumstances?", options:{A:"a, c and d",B:"b, e and f",C:"none",D:"all"}, correct:"B" },
  { id:153, set:"S13", question:"Which of the following statements relating to Convention 108 are correct?\n\na) Relates to the protection of individuals regarding the automatic processing of personal data.\nb) Established by the Council of Europe\nc) Is a legally binding international instrument.\nd) It was modernised in 2018.", options:{A:"a, b and d",B:"b, c and d",C:"a, c and d",D:"a, b, c and d"}, correct:"D" },
  { id:154, set:"S13", question:"Where an organisation is outside of the EU and is processing the data of EU Citizens, which of the following is correct?", options:{A:"The organisation would have to consider Article 27 concerning a representative, depending on the type of processing.",B:"GDPR does not apply as they don't have a main establishment in the EU.",C:"They would need to use an appropriate safeguard as per Article 46.",D:"They only need to provide a contact email or telephone number for data subjects."}, correct:"A" },
  { id:155, set:"S13", question:"What is true regarding the 2000 Charter of Fundamental Rights?", options:{A:"It only relates to data protection rights.",B:"It includes the protection of personal data, political, social, and economic rights.",C:"It replaced the data protection directive 95/46/EC.",D:"Only applies to the UK."}, correct:"B" },
  { id:156, set:"S13", question:"When would a controller need to comply with Article 36 prior consultation?", options:{A:"When they are changing their processors.",B:"When a DPIA has been conducted and indicates a high risk in the absence of any mitigating measures taken by the controller.",C:"When starting up a new company and you are going to process personal data.",D:"When drafting BCRs."}, correct:"B" },
  { id:157, set:"S13", question:"What does Article 33 state shall be provided by a controller when notifying a personal data breach to a supervisory authority?\n\na) Nature of the personal data breach\nb) Describe the likely consequences of the breach.\nc) Notify the SA without undue delay and not later than 72 hours.\nd) If a processor is also involved, then they would notify the SA directly and not tell the controller.", options:{A:"a, b and d",B:"a, b and c",C:"b, c and d",D:"a, c, and d"}, correct:"B" },
  { id:158, set:"S13", question:"In which of the below circumstances could a data subject exercise their right under Article 21, Right to Object?", options:{A:"Where there is a contract between the controller and the data subject.",B:"On grounds relating to the data subject's situation and the processing is based on Article 6(1) e or f.",C:"Where the controller is processing in compliance with a legal obligation.",D:"Where the data has been made public by the data subject."}, correct:"B" },
  { id:159, set:"S13", question:"What does Schedule 3 in the Data Protection Act 2018 relate to?", options:{A:"Contains exemptions for Crime and Taxation and protection of the rights of others.",B:"Contains exemptions from some provisions in respect of UK GDPR for Health, Social Work, Education and Child Abuse.",C:"Relates to Penalties that the ICO may issue.",D:"Refers to the Accreditation of certification providers."}, correct:"B" },
  { id:160, set:"S13", question:"An organisation wants to install CCTV in several areas/offices within their office buildings for security and monitoring purposes. A DPIA has been drafted, and the project team has approached you for advice. Aside from assessment of compliance with GDPR and DPA 2018, what other compliance aspects would need to be considered?", options:{A:"ICO codes of practice for CCTV and Employment only need to be considered.",B:"Only need to consider GDPR and DPA 18 and a data subject right to be informed as staff should expect some workplace monitoring.",C:"ICO Employment Code of Practice, CCTV code of practice and The Investigatory Powers (interception by Businesses etc. for monitoring and record-keeping purposes) Regulations.",D:"If you tell employees that the CCTV is being installed and you have identified your lawful basis as Article 6(1) f, legitimate interests, then you will be compliant."}, correct:"C" },
  { id:161, set:"S13", question:"Which areas below have statutory codes of practice issued by the ICO?\n\na) Data Sharing\nb) Age-Appropriate Design\nc) Direct Marketing\nd) Employment Practices", options:{A:"a, b, c and d",B:"a, b and d",C:"b, c and d",D:"a, b and c"}, correct:"D" },
  { id:162, set:"S13", question:"While Jim at Brown and Sons Ltd was working through the contracts with processors and joint controllers, he discovered that minimal records were being kept. Jim decides he needs a plan of action. To comply with GDPR, which of the following statements should Jim implement?\n\na) Jim tells the managers that they should each develop an idea of how to secure the personal data they look after; these ideas will then be documented so they can show they have records of processing activity.\nb) Jim tells the managers they must create an information asset list of all records, starting with; where they are held, who has access, who the recipients are, and what the potential risks to these records are.\nc) Jim tasks one manager to coordinate the departments and, using the ICO template, create a record of processing activity (ROPA) Excel worksheet.\nd) It is suggested that if they add plenty of firewalls to the computer systems, they should protect themselves from cyber-attacks.\ne) Brown and Sons' new Government contract requires them to introduce new technology; therefore, to demonstrate compliance with Article 5(2), the company will be adopting data protection by design and default approach.\nf) With all these new plans, Jim doesn't need to carry out a data protection impact assessment to consider and mitigate any risks.", options:{A:"a, c and f",B:"b, c, and e",C:"d, e and f",D:"b, c and d"}, correct:"B" },
  { id:163, set:"S13", question:"A social media site is being launched in the UK to cater to the attitudes, values, perceptions, beliefs, and behaviours of 14-year-old girls interested in fashion and music. It relies on the parent or guardian's consent to deliver the service.\n\nWhat mistake (if any) has the social media site made?", options:{A:"No mistake, as the data subject's consent is not required to process personal data.",B:"It has assumed it can rely on legitimate interest.",C:"It should be pre-notified to the ICO.",D:"The Privacy notice should be addressed to the data subject, and consent should be obtained to process personal data."}, correct:"D" },
  // SET 14
  { id:164, set:"S14", question:"The OECD – Organisation for Economic Co-operation and Development:", options:{A:"Organises cross-border marketing and sales.",B:"Identifies organisations that do not offer cross-border protection.",C:"Only relates to UK companies with cross-border transactions.",D:"Issued guidelines for the protection of privacy and trans-border dataflow of personal data."}, correct:"D" },
  { id:165, set:"S14", question:"Which of the following is NOT an 'identifier' for personal data?", options:{A:"A name.",B:"A cookie or IP address.",C:"A generic work email address.",D:"Cultural or social identity."}, correct:"C" },
  { id:166, set:"S14", question:"Which of the following best describes 'Pseudonymisation'?", options:{A:"Processes data in a manner that can no longer be attributed to a specific individual.",B:"Processes data in a manner that can no longer be attributed to a specific individual without the use of additional information.",C:"Processes data in a manner that can no longer be attributed to a specific individual without the use of additional information, which is kept secure and separately.",D:"Processes data in a manner that can no longer be attributed to a specific individual without the use of additional information, which is kept separately in a secure manner and only available for a fee."}, correct:"C" },
  { id:167, set:"S14", question:"Which of the following are NOT a Special Category of Personal Data?", options:{A:"Medical records of an individual.",B:"Details of ethnic origins.",C:"An individual's bank account details.",D:"The political opinion of a politician."}, correct:"C" },
  { id:168, set:"S14", question:"Assuming the following are all processing personal data, which one will be a Controller?", options:{A:"A sole trader running a market stall.",B:"Company Secretary of a Limited company.",C:"Treasurer of the local branch of a national bank.",D:"Head of regulatory compliance in a bank."}, correct:"A" },
  { id:169, set:"S14", question:"Which of the following may NOT need to be included in a Privacy Notice?", options:{A:"Whether it is a statutory or contractual requirement.",B:"The legal basis for processing.",C:"The recipients or categories of recipients of the personal data.",D:"The identities of all Processors."}, correct:"D" },
  { id:170, set:"S14", question:"Under the GDPR regimes and Data Protection Act, a Processor has:", options:{A:"A statutory requirement to offer a level of security equal to those imposed on a Controller.",B:"No statutory obligations, only contractual.",C:"A statutory duty to provide data subjects with subject access.",D:"A statutory duty to share data with other processors."}, correct:"A" },
  { id:171, set:"S14", question:"Which of the following is NOT a Principle under the GDPR regimes?", options:{A:"Purpose limitation.",B:"Storage limitation.",C:"Data Subject Rights.",D:"Integrity and confidentiality."}, correct:"C" },
  { id:172, set:"S14", question:"How can a controller prove compliance with the principles?", options:{A:"By complying with the accountability principle.",B:"By complying with the accessibility principle.",C:"By complying with the authorisation principle.",D:"By complying with the application principle."}, correct:"A" },
  { id:173, set:"S14", question:"Which of the following is NOT a data subject's right?", options:{A:"The right to object.",B:"The right to 3rd party's data.",C:"The right of access.",D:"The right to be informed."}, correct:"B" },
  { id:174, set:"S14", question:"A Main establishment under EU GDPR is:", options:{A:"A controller with businesses in more than one member state.",B:"A processor with businesses in more than one member state.",C:"The place of the central administration of a controller or processor with establishments in more than one member state.",D:"A place of the central administration of all controllers or processors, wherever their establishment is based."}, correct:"C" },
  { id:175, set:"S14", question:"What is the one-stop shop within the EU?", options:{A:"A shop that sells data protection products.",B:"A single point of contact to an ISA for cross-border processing by a controller or processor.",C:"A place a data subject can go to make a complaint.",D:"A place that covers co-operation and mutual assistance."}, correct:"B" },
  { id:176, set:"S14", question:"The GDPR regimes introduce provisions to ensure that profiling and automated individual decision-making are not used in ways that have an unjustified impact on individuals' rights; which of the following is NOT an example of these provisions?", options:{A:"Specified legal basis for processing.",B:"Inform the ICO of the planned processing.",C:"Greater accountability obligations.",D:"Rights to oppose profiling for marketing purposes."}, correct:"B" },
  { id:177, set:"S14", question:"When should a Data Protection Impact Assessment be carried out?", options:{A:"When a project is being designed.",B:"Once a decision has been set in stone.",C:"Once you have procured systems.",D:"Once contracts/agreements have been signed."}, correct:"A" },
  { id:178, set:"S14", question:"Which of the following would NOT be considered a security measure?", options:{A:"Security awareness training.",B:"ISO 9001.",C:"Data Protection Impact Assessments.",D:"Pseudonymisation."}, correct:"B" },
  { id:179, set:"S14", question:"Which of the following is NOT a required record of processing activities (ROPA)?", options:{A:"The purposes of the processing.",B:"A description of the categories of data subjects and the categories of personal data.",C:"Where possible, the envisaged time limits for erasure of the different categories of data.",D:"A process for regularly testing, assessing, and evaluating the effectiveness of technical and organisational measures for ensuring the security of the processing."}, correct:"D" },
  { id:180, set:"S14", question:"A 'data subject' is:", options:{A:"Any piece of information.",B:"Information about a person held on a computer.",C:"An identifiable living individual to whom the personal data relates.",D:"A person who inputs personal data into a computer."}, correct:"C" },
  { id:181, set:"S14", question:"When would explicit consent be required?", options:{A:"Processing a child's data.",B:"Processing all personal data.",C:"Processing data that is in the legitimate interests of the controller.",D:"Processing special categories of data."}, correct:"D" },
  { id:182, set:"S14", question:"Which of the following is personal data under GDPR?", options:{A:"IP addresses.",B:"Location data.",C:"DNA.",D:"All the above."}, correct:"D" },
  { id:183, set:"S14", question:"Which of the following would NOT be information processed within the definition of 'Data'?", options:{A:"A note taken over the phone that needs to be inputted onto a computer file.",B:"A random sheet of paper on a desk.",C:"CCTV footage.",D:"A personal reference stored alphabetically in a filing cabinet."}, correct:"B" },
  // SET 15
  { id:184, set:"S15", question:"The GDPR Article 4 definition of profiling includes which of the following?\n\na) Family history\nb) Economic situation\nc) Health\nd) Personal preferences", options:{A:"a, b, and d",B:"a, b, and c",C:"b, c, and d",D:"a, c, and d"}, correct:"C" },
  { id:185, set:"S15", question:"Personal data means any data connecting to:\n\na) Living individual\nb) Identified or identifiable individual\nc) Directly or indirectly identifiable individual\nd) Deceased individual", options:{A:"a and d",B:"a, b, and c",C:"a, b, c, and d",D:"a, c, and d"}, correct:"B" },
  { id:186, set:"S15", question:"A data subject has the right to be forgotten; in which of the following circumstances can this right be overridden?\n\na) Freedom of expression\nb) Public interest in public health\nc) To establish, exercise, or defend legal claims.\nd) To protect the vital interests of the data subject\ne) In the legitimate interest of the controller\nf) As ordered by the European Data Protection Board (EDPB)", options:{A:"d, e, and f",B:"a, b, and c",C:"a, b, and f",D:"a, c, and e"}, correct:"B" },
  { id:187, set:"S15", question:"Article 9(1) GDPR Special categories of personal data states processing shall be prohibited, unless which of the following applies?\n\na) Processing is necessary to protect the vital interests of the data subject or of another natural person where the data subject is physically or legally incapable of giving consent.\nb) The data subject has given explicit consent to the processing of those personal data for one or more specified purposes.\nc) Processing is necessary for the establishment, exercise, or defence of legal claims or whenever courts are acting in their judicial capacity.\nd) Processing relates to personal data which have not been made public by the data subject.", options:{A:"a, c, and d",B:"b, c, and d",C:"a, b, and c",D:"a, b and d"}, correct:"C" },
  { id:188, set:"S15", question:"GDPR Article 28(3)(f) says a Processor must assist the controller in ensuring compliance with Articles 32 to 36; which of the following are included?\n\na) The security of processing\nb) Notification of a personal data breach to the ICO\nc) Establishing legal claims\nd) Communication of a personal data breach to the data subject\ne) For the legitimate interests of the data subject\nf) Fulfilling Data Protection Impact Assessments", options:{A:"a, b, d and e",B:"a, b, d, and f",C:"a, c, e, and f",D:"b, c, d, and e"}, correct:"B" },
  { id:189, set:"S15", question:"An organisation provides its clients with medical and other services. The client contract states that goods linked to the services remain the organisation's property. The organisation provides client contact details to two key suppliers, who are paid for the goods provided to clients. The key suppliers are not working under the instruction of the controller.\n\nIn respect of the clients and suppliers in this case, what data protection issues must the organisation consider?\n\na) Obtain consent for the processing of health-related personal data.\nb) Provide a privacy notice that defines the legal basis for processing.\nc) Obtain authorisation from the ICO.\nd) Implementing a data sharing agreement with each of the suppliers.", options:{A:"a, b, and d",B:"b, c, and d",C:"c and d",D:"b and d"}, correct:"A" },
  { id:190, set:"S15", question:"The GDPR states that security measures SHOULD be taken against which of the following?\n\na) Damage to personal data.\nb) Unauthorised processing.\nc) Data leaving Europe.\nd) Unlawful processing.", options:{A:"a, b and d",B:"b and c",C:"c and d",D:"a, c and d"}, correct:"A" },
  { id:191, set:"S15", question:"Which of the below does Article 32 state is an appropriate security measure that a controller or processor should implement?\n\na) Staff should only be able to access systems between 9am and 5pm\nb) Pseudonymisation and encryption of data\nc) Ensure staff have Information Technology backgrounds\nd) Ensure the ability of ongoing confidentiality, integrity and resilience of processing systems and services", options:{A:"a, c, and d",B:"b, c, and d",C:"b and d",D:"a, b, and d"}, correct:"C" },
  { id:192, set:"S15", question:"PneumaticSpark has cornered the market in the UK for their specialist product to both the business and public market. Their marketing team now wants to capture the French market, and to this end, they decided to set up a new French website. They have contracted a French sales rep to deal with any calls and will collect and monitor all website traffic in the UK.\n\nWhich of the following would PneumaticSpark need to consider to comply with GDPR?\n\na) They are only based in the UK, so they would not be classed as having an 'establishment' in France.\nb) They don't have to have a physical presence in France; a single representative may be sufficient to be an 'establishment' where a specific country is being targeted.\nc) They offer goods and services to the French, including monitoring and cross-border processing.\nd) They don't need to consider Brexit; now the UK has left, it won't affect the UK company.\ne) PneumaticSpark should consider the need for a Representative as per Article 27.", options:{A:"b, c, and d",B:"a, d, and e",C:"a, c, and d",D:"b, c, and e"}, correct:"D" },
  { id:193, set:"S15", question:"Which of the following statements are FALSE?\n\na) Pseudonymisation is processing personal data so that the personal data can no longer be attributed to a specific data subject without using additional information.\nb) This data would no longer be classed as identified or identifiable regardless of where the additional information is held.\nc) Neither pseudonymised nor anonymous data fall under the scope of GDPR.\nd) Additional information must be kept separately and subject to technical and organisational measures to ensure the personal data are not identifiable.", options:{A:"a and b",B:"b and d",C:"a and d",D:"b and c"}, correct:"D" },
  { id:194, set:"S15", question:"When storing records about the 5th principle, which of the following statements would be Correct?\n\na) Keeping the data in a manner that can be identified for no longer than necessary for the purpose of the processing.\nb) Ensure that the period the personal data are stored is limited to a strict minimum.\nc) It is necessary to keep data in case the data subject requests access to it in the future.\nd) In line with other principles, the data collected and stored is limited to what is necessary.\ne) The controller should establish time limits for erasure or a periodic review.\nf) Always check with other areas of your organisation to see if they need it for any other purpose before erasing it.", options:{A:"a, b, d and e",B:"a, c, e and f",C:"b, d, e and f",D:"a, c, d and e"}, correct:"A" },
  { id:195, set:"S15", question:"The accountability obligations require the controller to be responsible and demonstrate compliance with the principles listed in Article 5(1). Which of the following would NOT need to be considered when demonstrating compliance?\n\na) Keeping records of processing activities\nb) Dealing with a breach in a timely manner and notifying the ICO unless the breach is unlikely to result in a risk to the data subject.\nc) Seek approval from the ICO of any new processor being engaged.\nd) Adopting a process of data protection by design and default\ne) Ensure that contentious issues are discussed verbally and not recorded.", options:{A:"a, and c",B:"a, b and d",C:"c and e",D:"b, c and e"}, correct:"C" },
  { id:196, set:"S15", question:"At a public authority meeting, it is suggested that all personal data should be kept centrally so all departments could update, access and share it whenever necessary. A dissenting voice says the groundwork department shouldn't have access to social care records, but this is quickly dismissed.\n\nWhich of the following statements would be correct about this scenario?\n\na) Departments would be unfairly processing and not processing for a specified, explicit, and legitimate purpose.\nb) The authority's legitimate grounds would be as part of their official task vested in the controller.\nc) The integrity and confidentiality of the data would be compromised, lacking appropriate security.\nd) Data minimisation would be compromised.\ne) The authority could also argue the case of processing for the controller's legitimate interests as overall, they are attempting to offer a better service to the public.\nf) Where special category data is being processed and accessed, the authority would be able to process it as it is of substantial public interest.", options:{A:"a, b, c and f",B:"a, c and d",C:"b, c and e",D:"d, e, and f"}, correct:"B" },
  { id:197, set:"S15", question:"One of the criteria for conducting a DPIA is that the processing is likely to risk individuals to the rights and freedoms; which of the following may not require a DPIA?", options:{A:"Evaluation and scoring, i.e., predicting performance at work, reliability or behaviour and personal preferences.",B:"Processing on a large scale.",C:"A previous assessment addresses a similar processing operation.",D:"Datasets that have been matched or combined that would exceed the reasonable expectations of the data subject."}, correct:"C" },
  { id:198, set:"S15", question:"Which of the following would generally be expected requirements for implementing appropriate technical and organisational measures to ensure a level of security appropriate to the risk?\n\na) Business continuity, i.e., ongoing confidentiality, integrity, availability, and resilience\nb) Credit reference check on all staff with access to any financial data\nc) Pseudonymisation and encryption\nd) DV security checks on staff every five years\ne) The ability to restore the availability and access to personal data in a timely manner following a physical or technical incident.\nf) Ethical hacking to ensure the security of the processing.", options:{A:"b, d, e and f",B:"a, c, e and f",C:"a, d and f",D:"b, c and d"}, correct:"B" },
  { id:199, set:"S15", question:"Which of the following could be a third party?\n\na) Police force you gave data to following a request relating to preventing and detecting crime.\nb) Data subject\nc) A company where there were legitimate conditions to share data.\nd) A company you have outsourced work to is processing it on your behalf.\ne) A recipient", options:{A:"a, c and e",B:"a, c and d",C:"b, and e",D:"c and d"}, correct:"A" },
  { id:200, set:"S15", question:"Which of the following is NOT a Corrective Power of the ICO?\n\na) The issuing of reprimands\nb) Ordering the controller to communicate a personal data breach to the data subject.\nc) To notify the controller or processor of an alleged infringement of GDPR\nd) To withdraw certification\ne) To carry out a data protection audit", options:{A:"a and e",B:"b and d",C:"c and d",D:"c and e"}, correct:"D" },
  { id:201, set:"S15", question:"A bank has moved its call centre operations to a company in India. They do not inform customers as customers still dial a UK number. One customer (James) has written to the bank to complain, claiming that his personal data is being processed in India without his consent.\n\nWhich of the following statements would be correct?\n\na) The processing is lawful as it is necessary for the performance of a contract.\nb) James has the right to object to the Controller processing using '6(1)(b) Performance of a contract.\nc) The controller is not required to include details of the safeguards for any transfers to 3rd countries under Articles 13 and 14.\nd) The bank would require a current 2010 controller to processor Standard contractual clause (SSC) or another safeguard to process in a third country.\ne) The relationship between the Bank and the Indian call centre is Controller and Processor.", options:{A:"a, c and d",B:"b, d and e",C:"a, d and e",D:"a, b and c"}, correct:"C" },
  { id:202, set:"S15", question:"Which of the following are classed as special category data under GDPR?\n\na) A criminal record\nb) A political opinion\nc) Trade Union membership\nd) Racial Origin\ne) A financial record", options:{A:"a, b, and c",B:"a, d, and e",C:"b, c, and d",D:"b, d, and e"}, correct:"C" },
  { id:203, set:"S15", question:"Which of the following organisations would be an essential service under the NIS Directive?", options:{A:"John Lewis plc",B:"Network Rail",C:"Hewlett Packard",D:"Debenhams"}, correct:"B" },
  // SET 16
  { id:204, set:"S16", question:"Which of the below relates to the definition of Biometric Data under GDPR?", options:{A:"Personal data that is held by the department that undertakes metrics.",B:"Personal data resulting from specific technical processing relating to a natural person's physical, physiological, or behavioural characteristics to allow unique identification.",C:"Personal data that is processed by a computer to monitor the behaviour of individuals.",D:"Personal data that relates to certain inherited or acquired characteristics of a natural person."}, correct:"B" },
  { id:205, set:"S16", question:"A local council wishes to undertake a quarterly staff survey about workplace morale; this type of processing would not be part of the council's public task, so which of the below would likely be the most suitable lawful basis for the council to use?", options:{A:"Contract.",B:"Legitimate Interests.",C:"Legal obligation.",D:"Vital Interests."}, correct:"B" },
  { id:206, set:"S16", question:"Which of the below are measures a controller could take to comply with Article 5(2) Accountability Principle?", options:{A:"Adopting a Data Protection by design and default approach.",B:"Having a DPIA process in place.",C:"Ensuring procedures are in place for documenting the processing activities where such relates to personal data.",D:"All of the above."}, correct:"D" },
  { id:207, set:"S16", question:"Which of the below would be an appropriate safeguard that could be used for a Controller who wants to transfer personal data to an international organisation that is going to process personal data on behalf of the controller?", options:{A:"Standard contractual clause (SSC).",B:"Nothing required as the controller has done business with them before.",C:"Data Sharing agreement.",D:"Binding Corporate Rule."}, correct:"A" },
  { id:208, set:"S16", question:"Your organisation wishes to offer services to children via an information society services platform. Which of the following would be one of the first considerations regarding consent the organisation would need to consider?", options:{A:"Ensure that the organisation has processes and procedures in place to comply with the conditions of Article 8 and DPA Part 2, Chapter 2, section 9.",B:"Have a default approach and always seek parental consent.",C:"You don't charge for the services you are offering, so Article 8 doesn't apply to you.",D:"You must have parental consent as you are offering preventative or counselling services."}, correct:"A" },
  { id:209, set:"S16", question:"Your company holds a database of customer data processed using the lawful basis of contract. The marketing department has decided to use this information to directly market customers about entirely different products. Which of the following statements would be false?", options:{A:"This is not a problem as the company owns the information, so marketing can use it as they wish.",B:"The personal data was collected for a different purpose, which will breach the GDPR.",C:"PECR will have to be complied with as well as GDPR.",D:"The company should consider undertaking a DPIA for this new type of processing."}, correct:"A" },
  { id:210, set:"S16", question:"You have recently started a new role as DPO. Upon initial assessment, you highlight that the organisation is unable to clearly identify the information it processes and any relevant processes/procedures. Which of the following would be the BEST first priority action for the DPO to undertake?", options:{A:"To work with any relevant departments to create a record of processing of the organisations processing activities as per Article 30.",B:"Collate all policies and procedures and start to update them.",C:"Put into place a staff awareness campaign relating to good data protection practices.",D:"Report the issue to the ICO."}, correct:"A" },
  { id:211, set:"S16", question:"An organisation receives a notice from a former customer who objects to their personal data being used for direct marketing purposes. What MUST the organisation do in response to the request?", options:{A:"Consider the request and whether to accept the objection and notify accordingly.",B:"Stop selling the customer's data to other companies.",C:"Amend the mailing list to ensure that no more marketing material is sent to the customer but leave the customer on the telesales list.",D:"Stop all marketing activities aimed at the customer, whether it involves telesales, mailing lists or third-party marketing."}, correct:"D" },
  { id:212, set:"S16", question:"Which of the following would NOT need to be included when reporting a data breach to the Supervisory Authority (ICO)?", options:{A:"The likely consequences of the personal data breach.",B:"Whether the processing was in the public's interest.",C:"Describe the nature of the personal data breach.",D:"Describe the measures taken or proposed to mitigate the adverse effects of the data breach."}, correct:"B" },
  { id:213, set:"S16", question:"The special purposes in the UK relate to:", options:{A:"Journalism, academic, artistic, and literary purposes.",B:"Personal data collated for genetic research.",C:"Personal data contained in educational records.",D:"Information relating to individuals employed by the security services."}, correct:"A" },
  { id:214, set:"S16", question:"An objection to processing for direct marketing is received from a data subject; what should you do?", options:{A:"Nothing and continue to direct market as believed to be in the Controller's legitimate interests.",B:"Contact the data subject and ask why they should stop.",C:"Stop processing the personal data.",D:"Notify the ICO of a breach."}, correct:"C" },
  { id:215, set:"S16", question:"When may an exemption be applied to the requirements of the 1st principle of providing fair processing to a data subject? For example, when data is used for which of the following?", options:{A:"Quality and monitoring purposes.",B:"Profiling.",C:"Testing an internal system.",D:"Disclosure to assist in a police investigation."}, correct:"D" },
  { id:216, set:"S16", question:"Which of the following would NOT be classed as the Main Establishment under EU GDPR?", options:{A:"The establishment of the Controllers central administration in Europe.",B:"The establishment of the Processors central administration in Europe.",C:"Another establishment where decisions are made by the controller on personal data within Europe.",D:"The presence of technical means and technologies to process personal data."}, correct:"D" },
  { id:217, set:"S16", question:"What information would be required to be made available to a 3rd party under a Privacy notice?", options:{A:"The purposes of the intended processing of the personal data and the legal basis for the processing.",B:"Any processing for archiving that is in the public interest.",C:"Statistical information.",D:"Information where the processing is required by law."}, correct:"A" },
  { id:218, set:"S16", question:"A controller may be able to use an exemption to withhold personal access to data relating to negotiations in which circumstances?", options:{A:"Pay, conditions and prospects.",B:"Because it is on a need-to-know basis, and you don't need to know.",C:"Because the exemption is there to be used.",D:"To give data controllers a free hand to do whatever they like."}, correct:"A" },
  { id:219, set:"S16", question:"Which of the following does PECR NOT directly provide rulings on?", options:{A:"Keeping communications services secure.",B:"Marketing mailshots (snail-mail).",C:"Cookies and similar technologies.",D:"Marketing by phone, email, text etc."}, correct:"B" },
  { id:220, set:"S16", question:"Which of the following is a task listed in the GDPR of a data protection officer?", options:{A:"Monitor staff and report back to HR.",B:"To act as the contact point for the supervisory authority on issues relating to processing, including the prior consultation, and to consult, where appropriate, regarding any other matter.",C:"Carry out assessments for the ICO.",D:"Work for HR."}, correct:"B" },
  { id:221, set:"S16", question:"When is the appointment of a DPO by a controller or processor NOT required?", options:{A:"When the processing is carried out by a public authority or body.",B:"Courts acting in their judicial capacity.",C:"Where the processing requires regular and systematic monitoring of data subjects.",D:"Large-scale processing of patient data as a regular part of business."}, correct:"B" },
  { id:222, set:"S16", question:"At what age is a child considered to have full capacity and mature enough to make their own data protection decisions involving information society services in the UK?", options:{A:"18 years.",B:"16 years.",C:"13 years.",D:"12 years."}, correct:"C" },
  { id:223, set:"S16", question:"Which of the following is NOT a condition to release confidential information?", options:{A:"Consent.",B:"Compulsion of law.",C:"Payment of a fee.",D:"Duty to the public."}, correct:"C" },
  // SET 17
  { id:224, set:"S17", question:"Special categories of personal data include:", options:{A:"Information about a data subject's finances.",B:"Details of a data subject's education.",C:"The employment record of a data subject.",D:"Religious or philosophical beliefs."}, correct:"D" },
  { id:225, set:"S17", question:"In GDPR, which of the following does NOT demonstrate compliance with the Accountability Principle (Article 5(2))?", options:{A:"Appointing a DPO.",B:"Keeping screening data on all job applicants for inspection.",C:"Data minimisation.",D:"Using DPIAs."}, correct:"B" },
  { id:226, set:"S17", question:"A 'processor' is:", options:{A:"An individual or legal person, public authority or other body who inputs data into a computer.",B:"An individual or legal person, public authority or other body who works for a data controller.",C:"An individual or legal person, public authority or other body who processes personal data on behalf of a controller.",D:"An individual or legal person, public authority or other body who makes decisions as to a data subject's creditworthiness."}, correct:"C" },
  { id:227, set:"S17", question:"The controller or processor may transfer personal data where the organisation receiving the personal data has provided adequate safeguards; which of the following is NOT an adequate safeguard?", options:{A:"Binding corporate rules.",B:"Standard data protection clauses adopted by the Commission.",C:"A long-standing relationship between the organisations concerned.",D:"Certification under an approved certification mechanism."}, correct:"C" },
  { id:228, set:"S17", question:"Which steps would NOT be taken by a controller to ensure a reliable processor?", options:{A:"Make sure the Processor maintains an annual fee to the controller.",B:"Visit the Processor's premises to check physical security measures.",C:"Request details of procedures for disposing of personal data.",D:"Ensure new staff receive training on data protection."}, correct:"A" },
  { id:229, set:"S17", question:"If a controller engages a processor, he should ensure that the processor:", options:{A:"Can implement appropriate security measures to meet the requirements of the Regulations.",B:"Has carried out credit checks on all employees.",C:"Has installed a firewall.",D:"Has carried out work for the Controller in the past."}, correct:"A" },
  { id:230, set:"S17", question:"Assuming the following are all processing personal data, which one will be a Data Controller?", options:{A:"A housewife running a creche from home.",B:"Company Secretary of a Limited company.",C:"Treasurer of the local branch of a national bank.",D:"Head of regulatory compliance in a bank."}, correct:"A" },
  { id:231, set:"S17", question:"Complete the following statement relating to principle 5, (Article 5(1)(e)) – 'storage limitation, personal data should':", options:{A:"Not be kept for longer than three months.",B:"Be kept for up to 100 years.",C:"Not be kept for longer than is necessary.",D:"Be stored in case it becomes useful to the data controller."}, correct:"C" },
  { id:232, set:"S17", question:"When might a fee for a subject access request be charged?", options:{A:"Every request for personal data.",B:"Any requests that may take a few hours to complete.",C:"When the request is manifestly unfounded or excessive.",D:"When the controller needs to increase income."}, correct:"C" },
  { id:233, set:"S17", question:"Which of the following is NOT a requirement of access concerning Article 15?", options:{A:"A security statement and how the data is protected.",B:"The right to lodge a complaint with the ICO (Supervisory Authority).",C:"Out of working hours, contact point.",D:"The envisaged period for which the personal data will be stored."}, correct:"C" },
  { id:234, set:"S17", question:"As the data protection officer, advise the best action your CEO should take following a breach of security by your private sector organisation involving children's data likely to cause serious risk.", options:{A:"You have 72 hours from becoming aware of the breach to notify the ICO.",B:"You must report any breach involving children's data within a month.",C:"You only need to report some breaches involving the loss of personal data.",D:"It is a breach of your security policy to notify anyone, including the ICO."}, correct:"A" },
  { id:235, set:"S17", question:"Controllers and Processors must maintain a record of processing activities (ROPA) under their responsibilities. Which of the following is NOT a requirement to maintain records?", options:{A:"The Controller or processor has more than 250 staff.",B:"The processor must maintain records of processing activities carried out on behalf of the controller.",C:"Only relates to companies whose staff are based in third countries.",D:"No minimum staff numbers where the processing is likely to result in a risk to the rights and freedoms of data subjects."}, correct:"C" },
  { id:236, set:"S17", question:"What is the maximum tenure of the Information Commissioner?", options:{A:"5 years.",B:"7 years.",C:"10 years.",D:"Life."}, correct:"B" },
  { id:237, set:"S17", question:"A private citizen has a CCTV camera on his house; he believes he is exempt from data protection; which of the following must be true for him to be correct?", options:{A:"He only uses the CCTV in the evenings.",B:"He only shares the data with the Police.",C:"He never publishes the data on the internet.",D:"He only captures data on his property."}, correct:"D" },
  { id:238, set:"S17", question:"Which of the following Data Protection Officer (DPO) statements is true?", options:{A:"All companies subject to enforcement require a DPO.",B:"Public authorities and public bodies require a DPO except where an exemption applies.",C:"Only marketing companies require a DPO.",D:"The ICO will issue a list of sectors that will require a DPO."}, correct:"B" },
  { id:239, set:"S17", question:"A University maintains records of past students and their qualifications. To comply with Principle 4 (Article 5(1)(d)) Accuracy, which records would you be required to update?", options:{A:"Where there is an ongoing relationship.",B:"All records.",C:"Limit to 3–5 years.",D:"No specific circumstances."}, correct:"A" },
  { id:240, set:"S17", question:"Can 'everything you hold on me' be asked for in a subject access request?", options:{A:"Only specific information can be requested.",B:"Never.",C:"It can, but the Data Controller may require further information to help locate everything.",D:"Yes, but the controller can charge whatever they like."}, correct:"C" },
  { id:241, set:"S17", question:"Which of the following is least likely to be a breach under GDPR?", options:{A:"Emails are disposed of after 60 days unless staff save for a specified retention period.",B:"All emails are kept for a minimum of 10 years.",C:"All emails are archived and automatically deleted when the storage reaches a defined level.",D:"No rules for emails are required."}, correct:"A" },
  { id:242, set:"S17", question:"Which of the following would be wholly exempt from the Data Protection Principles?", options:{A:"A home video including images of the Prime Minister as a child.",B:"A professional photographer is taking photos of the Prime Minister with consent.",C:"The Electoral Roll publicly showed the Prime Ministers' home address.",D:"An official drawing of a caricature of the Prime Minister."}, correct:"A" },
  { id:243, set:"S17", question:"Who is responsible for determining the purposes and means for processing personal data?", options:{A:"Controller.",B:"Supervisory Authority.",C:"Processor.",D:"Data Subject."}, correct:"A" },
  // SET 18
  { id:244, set:"S18", question:"Article 14, where personal data has not been collected from the data subject, which of the following is a correct statement of when the information should be provided?", options:{A:"If the data are to be used to communicate with the individual, at the latest when the first communication occurs.",B:"Never.",C:"At the start of the processing or whenever practicable after that time.",D:"Whenever is practicable within a reasonable period if the data subject pays a fee."}, correct:"A" },
  { id:245, set:"S18", question:"A political party maintains a database of its members' contact details. It processes the special category of personal data using the GDPR condition Article 9 2(d). Which of the following activities are NOT covered?", options:{A:"Arranging the booking of coaches to travel to the party's annual conference.",B:"Distribution of a public newsletter that is developed and printed in-house.",C:"Informing members of the upcoming election of new committee members.",D:"Provision of members' and supporter's details to the hotel that is being used for the conference."}, correct:"B" },
  { id:246, set:"S18", question:"A company wishes to market a special offer to people who have emailed to enquire about opening times. Would this be permissible under the Privacy and Electronic Communication Regulations (PECR)?", options:{A:"Yes, because it is covered under the soft-opt-in.",B:"Yes, because the person shouldn't have enquired if they didn't expect to receive marketing messages.",C:"No, because there is no consent.",D:"They cannot use the email address because they haven't obtained consent, and the soft-opt-in does not cover it."}, correct:"D" },
  { id:247, set:"S18", question:"Which of the following would be required to ensure GDPR processing by design?", options:{A:"Appropriate technical and organisational measures like pseudonymisation.",B:"Integrate the necessary safeguards.",C:"Neither.",D:"Both."}, correct:"D" },
  { id:248, set:"S18", question:"Special categories of personal data may be processed if:", options:{A:"The controller is processing to prevent or detect crime.",B:"The data subject is applying for a financial service.",C:"The data subject has a notifiable disease.",D:"The data subject is physically or legally incapable of giving consent, and the processing is in their vital interests."}, correct:"D" },
  { id:249, set:"S18", question:"Complete the following sentence: 'The processing of personal data is lawful if...'", options:{A:"The processing is necessary for a task carried out in the public interest.",B:"The data subject resides in the EU.",C:"The controller has carried out a data privacy impact assessment.",D:"The personal data is encrypted."}, correct:"A" },
  { id:250, set:"S18", question:"How long does a controller normally have to deal with a request from a data subject to rectify recorded inaccurate personal data under GDPR?", options:{A:"Must do instantly.",B:"One month.",C:"40 calendar days.",D:"No specific time but must be reasonable."}, correct:"B" },
  { id:251, set:"S18", question:"Which best describes the principle of data minimisation?", options:{A:"Care must be taken to collect as little data as possible to protect privacy and the interests of the data subject.",B:"The number of forms that are collected per data subject must not exceed the upper limit stated by the Data Protection Authority (DPA).",C:"Data must be adequate, relevant, and limited to what is necessary in relation to the purposes for which they are processed.",D:"Data must be manageable and kept in a manner that requires a minimal amount of storage."}, correct:"C" },
  { id:252, set:"S18", question:"Which of the following MUST be done when a controller wants to outsource the processing of personal data?", options:{A:"The processor must have a service level agreement.",B:"The controller must ask the ICO for permission to outsource the personal data.",C:"The controller must ask the ICO if the written contract is compliant with the regulations.",D:"The controller must ensure that the processor guarantees compliance with the GDPR and should seek evidence and documentation from the processor."}, correct:"D" },
  { id:253, set:"S18", question:"Which of the following is not covered under PECR (Privacy & Electronic Communications 2003)?", options:{A:"Postal Mailings.",B:"Texts.",C:"Email.",D:"Cookies."}, correct:"A" },
  { id:254, set:"S18", question:"What type of breach in GDPR is 'unauthorised disclosure of, or access to, personal data'?", options:{A:"Confidentiality breach.",B:"Security Incident.",C:"Personal data breach.",D:"Security breach."}, correct:"C" },
  { id:255, set:"S18", question:"When a controller obtains personal data from a third party (Article 14), what information MUST be provided to the data subject under Article 14(1)?", options:{A:"The period for which the personal data will be stored, or the criteria used to determine that period.",B:"The right to lodge a complaint with the ICO (Supervisory Authority).",C:"The source from which the personal data originated and, if applicable, whether it came from publicly accessible sources.",D:"The recipients of the personal data (if any)."}, correct:"D" },
  { id:256, set:"S18", question:"Which of the following describes the MOST LIKELY breach of the GDPR?\n\nThe disclosure of personal data which are subject to a professional or common law duty of confidentiality can occur if…", options:{A:"A disclosure is made to the police to help investigate a serious crime.",B:"A local authority demands the disclosure regarding a data subjects benefit claim.",C:"The relative of a mentally ill data subject needs the information to ensure that the data subject takes their medicine to stabilise their emotional state.",D:"The disclosure to an investigative journalist to expose the data subject as being promiscuous."}, correct:"D" },
  { id:257, set:"S18", question:"Third-party data:", options:{A:"Must not be released.",B:"Must always be redacted.",C:"Can be released if it is reasonable to do so.",D:"Can only be released where an exemption applies."}, correct:"C" },
  { id:258, set:"S18", question:"What are joint controllers?", options:{A:"Two or more organisations working together where one is the main controller and the other is the processor.",B:"Where two or more controllers jointly determine the purpose and means of processing.",C:"Where two or more processors jointly determine the purpose and means of processing.",D:"Where two or more processors join together to become controllers."}, correct:"B" },
  { id:259, set:"S18", question:"A Representative for Controllers and Processors not based in the European Union does NOT apply to which of the following?", options:{A:"Where personal data of EU citizens are not being processed.",B:"The offering of goods and services.",C:"The monitoring of processing taking place within the European Union.",D:"Processing personal data where Member state law applies."}, correct:"A" },
  { id:260, set:"S18", question:"A 'processor' under GDPR is a natural or legal person, public authority, agency, or other body who:", options:{A:"Inputs data into a computer on behalf of the controller.",B:"Is employed by the controller.",C:"Processes personal data on behalf of the controller.",D:"Makes decisions as to the data subject's creditworthiness."}, correct:"C" },
  { id:261, set:"S18", question:"As the Data Protection Officer, advise the best action your CEO should take following a breach of security by your private sector organisation involving children's data.", options:{A:"It's good practice to report serious breaches to ICO but not a legal obligation.",B:"You must report a breach if it involves children's data.",C:"It is a legal requirement to report any breach involving risk to the data subject within 72 hours of becoming aware of the breach.",D:"It is a breach of your security policy to notify anyone, including the ICO, of any personal data breach."}, correct:"C" },
  { id:262, set:"S18", question:"A local council sends applicants for an office role a general questionnaire that includes specific questions about health conditions that are only relevant to manual occupations of the council. In this context, which of the following is true of the questionnaire under GDPR?", options:{A:"This is in alignment with the data protection principles.",B:"The council has a legitimate interest in asking the questions.",C:"This does not comply with the principle of data minimisation as asking such questions is irrelevant and excessive.",D:"It doesn't fall under GDPR."}, correct:"C" },
  { id:263, set:"S18", question:"Under what circumstances can a data subject enforce their right to restrict the processing of personal data?", options:{A:"When the processing has been carried out by automated means.",B:"Where the processing has been collected concerning the offer of information society services.",C:"Where the data subject contests the accuracy of the personal data.",D:"Where the processing is for direct marketing."}, correct:"C" },
  // SET 19
  { id:264, set:"S19", question:"When did the GDPR become enforceable?", options:{A:"1998.",B:"2003.",C:"2018.",D:"2016."}, correct:"C" },
  { id:265, set:"S19", question:"What is the purpose of Pseudonymisation?", options:{A:"It makes it impossible to attribute a piece of data to a specific person without additional information.",B:"It mitigates the requirement for consent.",C:"It encrypts data so it cannot be read if accessed by hackers.",D:"It negates the requirement to fulfil a Data Subject Access Request."}, correct:"A" },
  { id:266, set:"S19", question:"Which of the following is NOT one of the GDPR data protection principles?", options:{A:"Data Minimisation.",B:"Purpose Limitation.",C:"Data Encryption.",D:"Storage Limitation."}, correct:"C" },
  { id:267, set:"S19", question:"A company wants to use contact data obtained from business websites and social media profiles to contact companies for marketing purposes. Identify the MOST appropriate lawful basis for processing:", options:{A:"Consent.",B:"Business to business.",C:"Legitimate interests.",D:"Contract."}, correct:"C" },
  { id:268, set:"S19", question:"Which of these conditions may be used to process special category data?", options:{A:"Legitimate interests.",B:"Public health.",C:"Contract.",D:"Profiling."}, correct:"B" },
  { id:269, set:"S19", question:"Which BEST describes the purpose of a Data Protection Impact Assessment (DPIA)?", options:{A:"To ensure personal data is encrypted.",B:"To assist in effectively tracking consent.",C:"To help you identify and minimise the data protection risks of a project.",D:"To help you decide if you can use legitimate interests as a lawful basis."}, correct:"C" },
  { id:270, set:"S19", question:"Article 30 of the GDPR states that you must:", options:{A:"Respond to Data Subject Requests within 72 hours.",B:"Keep records of all of your processing activities.",C:"Ensure that all 3rd party processors encrypt their databases.",D:"Unsubscribe users after one year of inactivity."}, correct:"B" },
  { id:271, set:"S19", question:"Which BEST describes data protection by design and default?", options:{A:"Employing a dedicated Data Protection Officer to ensure policies are in place.",B:"Always using the best available security solution for any personal data.",C:"Put in place appropriate technical and organisational measures to implement the data protection principles and safeguard individual rights.",D:"Ensuring consent is always obtained when processing personal data."}, correct:"C" },
  { id:272, set:"S19", question:"Which of the following statements regarding Data Protection Officers is FALSE?", options:{A:"The DPO must report to the highest management level.",B:"A DPO may perform additional job roles.",C:"The DPO must be a permanent employee.",D:"A DPO's role has a protected status."}, correct:"C" },
  { id:273, set:"S19", question:"To whom does Article 30 Records of Processing apply?", options:{A:"Controllers have sole responsibility for records of processing.",B:"Processors and controllers are both required to maintain records of processing.",C:"Processors have sole responsibility for records of processing.",D:"Processors, controllers, and data subjects are each responsible for their own records of processing."}, correct:"B" },
  { id:274, set:"S19", question:"When processing personal data under authority of the controller or processor, a processor may process data on instructions from the controller and also:", options:{A:"Under Legitimate Interests.",B:"For business-to-business marketing.",C:"For service messages only.",D:"Where required to do so by Union or Domestic Law."}, correct:"D" },
  { id:275, set:"S19", question:"What is the purpose of an EU Commission adequacy decision/UK Adequacy regulations?", options:{A:"Where adequacy is granted, a company may conduct specific processing of personal data without consent.",B:"When adequacy is in place, the ICO permits companies to leave databases unencrypted with suitable mitigating controls.",C:"It's a formal notice that a company may forgo compliance with any one of the data protection principles.",D:"Companies may execute restricted transfers without further approval where adequacy is in place."}, correct:"D" },
  { id:276, set:"S19", question:"You are tasked with creating a company policy for handling Data Subject Requests. Select an appropriate policy statement:", options:{A:"Data Subject Requests must be responded to within 72 hours.",B:"Data Subject Requests must be submitted in writing to the DPO.",C:"A Subject Access Request can be refused if it is excessive.",D:"A Subject Access Request can be refused if it includes financial transactions."}, correct:"C" },
  { id:277, set:"S19", question:"Under which circumstances may a Data Subject Request be refused?", options:{A:"Releasing the data could be damaging to the business.",B:"It involves disclosing personal information about other people.",C:"The Data Subject is under the age of 14.",D:"The Data Subject has refused to pay the fee."}, correct:"B" },
  { id:278, set:"S19", question:"What assistance does the ICO offer companies in achieving and maintaining compliance with the GDPR?", options:{A:"Conducting data protection audits for UK companies.",B:"Advise on appropriate wording for consent statements and privacy policies for your website.",C:"Provides data protection courses for the public.",D:"Liaises with the European Data Protection Board (EDPB) on behalf of UK companies."}, correct:"A" },
  { id:279, set:"S19", question:"Select the enforcement action that the ICO may take in the event of a compliance breach:", options:{A:"Order the company to pay compensation to the data subjects.",B:"Prosecute the shareholders of the company.",C:"Issue enforcement notices.",D:"Dock salaries of the company directors."}, correct:"C" },
  { id:280, set:"S19", question:"Under which circumstances are personal data breaches NOT reportable to the Supervisory Authority/ICO?", options:{A:"There is minimal risk to the data subject.",B:"It could make the company liable to legal action by the data subject.",C:"The data was breached by a third-party data processor.",D:"The company does not conduct large-scale, systematic processing of data."}, correct:"A" },
  { id:281, set:"S19", question:"A company experiences a theft of a database containing customers' personal information. The ICO investigates and finds: no state-of-the-art security controls, no DPIA conducted, data subjects not notified despite clear risk, and this is the first reportable incident.\n\nWhat is the maximum financial penalty that could be incurred under GDPR?", options:{A:"4% of the company's global annual turnover or €20 million/£17.5 million.",B:"£20,000,000.",C:"€10 million/£8.7 million or 2% of the company's global annual turnover.",D:"£500,000."}, correct:"A" },
  { id:282, set:"S19", question:"Your company wishes to contact potential customers to inform them of a change to the products it offers. The current database does not have proper consent under GDPR and there are no suitable grounds for legitimate interests.\n\nWhat method of communication is NOT prohibited by PECR or the GDPR?", options:{A:"SMS.",B:"None.",C:"Letters.",D:"Business to business (B2B) emails."}, correct:"C" },
  { id:283, set:"S19", question:"You've been asked to redesign your company's marketing strategy to ensure it is fully compliant with data protection law. Choose the CORRECT statement below:", options:{A:"Consent gained under PECR does not have to meet GDPR specifications.",B:"PECR applies to B2B marketing, GDPR does not.",C:"The GDPR replaced the PECR in 2018.",D:"Electronic marketing campaigns must comply with PECR AND GDPR."}, correct:"D" },
]; // END Q — do not add set definitions above this line

// ============================================================
const PASS_MARK = 0.65;
const SECS_PER_Q = (90 * 60) / 40;
const OPTS = ["A","B","C","D"];

function shuffle(a) { return [...a].sort(() => Math.random() - 0.5); }
function fmt(s) { return `${Math.floor(s/60).toString().padStart(2,"0")}:${(s%60).toString().padStart(2,"0")}`; }
function pill(border, color, bg) {
  return { fontSize:13, fontWeight:700, padding:"3px 12px", borderRadius:20, border:`1.5px solid ${border}`, color, background:bg, whiteSpace:"nowrap" };
}

// Dark theme palette
const T = {
  text:      "#e2e2e2",
  textMuted: "#9a9a9a",
  textDim:   "#6b6b6b",
  card:      "#2d2d2d",
  cardAlt:   "#363636",
  border:    "#4a4a4a",
  borderFaint:"#3a3a3a",
  accent:    "#7b9dd4",
  accentBg:  "#2a3549",
  accentBorder:"#4a6490",
  green:     "#4ade80",
  greenBg:   "#0f2918",
  greenBorder:"#22543d",
  red:       "#f87171",
  redBg:     "#2d1212",
  redBorder: "#7f1d1d",
  amber:     "#fbbf24",
  amberBg:   "#2d2008",
};

function Switch({ on, toggle }) {
  return (
    <div onClick={e => { e.stopPropagation(); toggle(); }}
      style={{ width:52, height:28, borderRadius:99, background:on?"#1e3a8a":"#cbd5e1", cursor:"pointer", position:"relative", transition:"background 0.25s", flexShrink:0 }}>
      <div style={{ position:"absolute", top:3, left:on?27:3, width:22, height:22, borderRadius:"50%", background:"#fff", boxShadow:"0 1px 4px rgba(0,0,0,0.2)", transition:"left 0.25s" }} />
    </div>
  );
}

export default function App() {
  const [screen, setScreen]             = useState("setup");
  const [numQ, setNumQ]                 = useState(10);
  const [showAns, setShowAns]           = useState("each");
  const [useTimer, setUseTimer]         = useState(true);
  const [selectedSets, setSelectedSets] = useState(() => SETS.map(s => s.id));
  const [questions, setQuestions]       = useState([]);
  const [cur, setCur]                   = useState(0);
  const [answers, setAnswers]           = useState({});
  const [submitted, setSubmitted]       = useState({});
  const [timeLeft, setTimeLeft]         = useState(0);
  const [timedOut, setTimedOut]         = useState(false);
  const [confirmEnd, setConfirmEnd]     = useState(false);
  const timerRef = useRef(null);

  const activePool = Q.filter(q => selectedSets.includes(q.set));
  const maxQ       = activePool.length;
  const allocSecs  = Math.round(numQ * SECS_PER_Q);
  const allocMins  = Math.floor(allocSecs / 60);
  const allocRem   = allocSecs % 60;

  useEffect(() => {
    if (screen === "question" && useTimer) {
      timerRef.current = setInterval(() => {
        setTimeLeft(t => {
          if (t <= 1) { clearInterval(timerRef.current); setTimedOut(true); setScreen("results"); return 0; }
          return t - 1;
        });
      }, 1000);
    }
    return () => clearInterval(timerRef.current);
  }, [screen, useTimer]);

  function toggleSet(id) {
    setSelectedSets(prev => {
      if (prev.includes(id) && prev.length === 1) return prev;
      const next = prev.includes(id) ? prev.filter(s => s !== id) : [...prev, id];
      const newMax = Q.filter(q => next.includes(q.set)).length;
      setNumQ(n => Math.min(n, newMax));
      return next;
    });
  }

  function startExam() {
    const q = shuffle(activePool).slice(0, numQ);
    setQuestions(q); setCur(0); setAnswers({}); setSubmitted({});
    setTimedOut(false); setConfirmEnd(false); setTimeLeft(allocSecs); setScreen("question");
  }
  function restart() {
    clearInterval(timerRef.current);
    setScreen("setup"); setAnswers({}); setSubmitted({}); setCur(0); setTimedOut(false); setConfirmEnd(false);
  }
  function finishExam() { clearInterval(timerRef.current); setScreen("results"); }

  const timerWarn   = useTimer && timeLeft <= 300 && timeLeft > 0;
  const timerDanger = useTimer && timeLeft <= 60  && timeLeft > 0;
  const timerColor  = timerDanger ? "#dc2626" : timerWarn ? "#d97706" : "#1e3a8a";
  const timerBg     = timerDanger ? "#fef2f2" : timerWarn ? "#fffbeb" : "#eff6ff";

  if (screen === "setup") return (
    <div className="setup-wrap"><div className="setup-card">
      <div style={{ display:"inline-block", background:"#1e3a8a", color:"#fff", fontSize:11, fontWeight:700, letterSpacing:2, padding:"4px 10px", borderRadius:4, marginBottom:12 }}>BCS MOCK EXAM</div>
      <h1 style={{ fontSize:24, fontWeight:700, color:"#0f172a", margin:"0 0 4px" }}>Steve - BCS DP Practitioner Mock</h1>
      <p style={{ color:"#64748b", fontSize:15, margin:"0 0 28px" }}>Configure your session below</p>

      <div style={{ marginBottom:24 }}>
        <label style={{ fontWeight:600, color:"#1e293b", fontSize:15, display:"block", marginBottom:8 }}>Question sets</label>
        <div style={{ display:"flex", gap:8, flexWrap:"wrap", marginBottom:10 }}>
          {SETS.map(set => {
            const active = selectedSets.includes(set.id);
            return (
              <button key={set.id} onClick={() => toggleSet(set.id)}
                style={{ padding:"7px 16px", borderRadius:20, border:`1.5px solid ${active?"#1e3a8a":"#cbd5e1"}`, background:active?"#1e3a8a":"#f8fafc", color:active?"#fff":"#475569", fontWeight:600, fontSize:13, cursor:"pointer" }}>
                {active ? "✓ " : ""}{set.label}
              </button>
            );
          })}
          {(() => {
            const allSelected = SETS.every(s => selectedSets.includes(s.id));
            return (
              <button onClick={() => {
                if (allSelected) {
                  setSelectedSets([SETS[0].id]);
                  setNumQ(n => Math.min(n, Q.filter(q => q.set===SETS[0].id).length));
                } else {
                  setSelectedSets(SETS.map(s => s.id));
                  setNumQ(n => Math.min(n, Q.length));
                }
              }} style={{ padding:"7px 16px", borderRadius:20, border:`1.5px solid ${allSelected?"#dc2626":"#16a34a"}`, background:allSelected?"#fef2f2":"#f0fdf4", color:allSelected?"#dc2626":"#16a34a", fontWeight:600, fontSize:13, cursor:"pointer" }}>
                {allSelected ? "Clear All" : "Add All"}
              </button>
            );
          })()}
        </div>
        <div style={{ background:"#f8fafc", border:"1px solid #e2e8f0", borderRadius:8, padding:"10px 14px", display:"flex", flexDirection:"column", gap:4 }}>
          {SETS.filter(s => selectedSets.includes(s.id)).map(set => (
            <div key={set.id} style={{ fontSize:13, color:"#475569" }}>
              <strong style={{ color:"#1e3a8a" }}>{set.label}:</strong> {set.description}
            </div>
          ))}
        </div>
      </div>

      <div style={{ marginBottom:24 }}>
        <label style={{ fontWeight:600, color:"#1e293b", fontSize:15, display:"block", marginBottom:4 }}>Number of questions</label>
        <p style={{ color:"#94a3b8", fontSize:13, margin:"0 0 10px" }}>Selected pool contains {maxQ} questions</p>
        <div style={{ display:"flex", alignItems:"center", gap:12 }}>
          <input type="range" min={1} max={maxQ} value={Math.min(numQ, maxQ)} onChange={e => setNumQ(+e.target.value)} />
          <span style={{ fontWeight:700, fontSize:20, color:"#1e3a8a", minWidth:32, textAlign:"right" }}>{Math.min(numQ, maxQ)}</span>
        </div>
        <div style={{ display:"flex", gap:8, marginTop:10, flexWrap:"wrap" }}>
          {[...new Set([5,10,20,40,maxQ].filter(v => v <= maxQ))].map(n => (
            <button key={n} onClick={() => setNumQ(n)} style={numQ===n
              ? { padding:"6px 16px", borderRadius:8, border:"1.5px solid #1e3a8a", background:"#1e3a8a", color:"#fff", fontWeight:600, cursor:"pointer", fontSize:14 }
              : { padding:"6px 16px", borderRadius:8, border:"1.5px solid #cbd5e1", background:"#f8fafc", color:"#475569", fontWeight:600, cursor:"pointer", fontSize:14 }}>
              {n === maxQ ? "All" : n}
            </button>
          ))}
        </div>
      </div>

      <div style={{ marginBottom:24 }}>
        <div style={{ display:"flex", alignItems:"center", gap:14, cursor:"pointer" }} onClick={() => setShowAns(s => s==="each"?"end":"each")}>
          <Switch on={showAns==="each"} toggle={() => setShowAns(s => s==="each"?"end":"each")} />
          <span style={{ fontSize:15, fontWeight:600, color:"#1e293b" }}>Show correct answers — <span style={{ fontWeight:400, color:"#64748b" }}>{showAns==="each"?"after each question":"at the end only"}</span></span>
        </div>
      </div>
      <div style={{ marginBottom:24 }}>
        <div style={{ display:"flex", alignItems:"center", gap:14, cursor:"pointer" }} onClick={() => setUseTimer(t => !t)}>
          <Switch on={useTimer} toggle={() => setUseTimer(t => !t)} />
          <span style={{ fontSize:15, fontWeight:600, color:"#1e293b" }}>Exam timer — <span style={{ fontWeight:400, color:"#64748b" }}>{useTimer ? `${allocMins}m${allocRem>0?` ${allocRem}s`:""} allowed` : "no time limit"}</span></span>
        </div>
        {useTimer && (
          <div style={{ marginTop:10, fontSize:14, color:"#1e3a8a", background:"#eff6ff", border:"1px solid #bfdbfe", borderRadius:8, padding:"8px 12px" }}>
            ⏱ Time allowed: <strong>{allocMins}m{allocRem>0?` ${allocRem}s`:""}</strong>
            <span style={{ color:"#64748b", fontSize:13 }}> (based on 90 mins per 40 questions)</span>
          </div>
        )}
      </div>

      <div style={{ background:"#f8fafc", border:"1px solid #e2e8f0", borderRadius:10, padding:"14px 18px", display:"flex", flexDirection:"column", gap:6, fontSize:14, color:"#475569", marginBottom:24 }}>
        <span>✅ Pass mark: <strong>65%</strong></span>
        <span>🎲 Questions are randomised each session</span>
      </div>
      <button onClick={startExam} style={{ width:"100%", padding:"14px", background:"#1e3a8a", color:"#fff", fontWeight:700, fontSize:16, border:"none", borderRadius:10, cursor:"pointer" }}>
        Start Exam →
      </button>
    </div></div>
  );

  if (screen === "question") {
    const q            = questions[cur];
    const progress     = (Object.keys(submitted).length / questions.length) * 100;
    const correctSoFar = Object.entries(submitted).filter(([i]) => answers[i] === questions[i].correct).length;
    const isSub        = !!submitted[cur];
    const sel          = answers[cur] || null;
    const setLabel = SETS.find(s => s.id === q.set)?.label.replace("Set ","Set-") ?? q.set;
    const setQNum  = Q.filter(qq => qq.set === q.set).findIndex(qq => qq.id === q.id) + 1;

    return (
      <div className="exam-wrap"><div className="exam-card">
        <div className="exam-header">
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10 }}>
            <span style={{ fontSize:13, color:"#64748b", fontWeight:600 }}>
              <strong style={{ color:"#1e293b" }}>{cur+1} of {questions.length}</strong>
              &nbsp;&nbsp;
              <span style={{ fontWeight:400 }}>({setLabel} · Q-{String(setQNum).padStart(2,"0")})</span>
            </span>
            <div style={{ display:"flex", gap:8, alignItems:"center" }}>
              {useTimer && <span style={pill(timerColor, timerColor, timerBg)}>⏱ {fmt(timeLeft)}</span>}
              <span style={pill("#1e3a8a","#1e3a8a","#eff6ff")}>Score: {correctSoFar}/{Object.keys(submitted).length}</span>
              {confirmEnd ? (
                <span style={{ display:"flex", gap:6, alignItems:"center" }}>
                  <span style={{ fontSize:12, color:"#dc2626", fontWeight:600 }}>End exam?</span>
                  <button onClick={() => { setConfirmEnd(false); finishExam(); }} style={{ ...pill("#dc2626","#fff","#dc2626"), cursor:"pointer" }}>Yes</button>
                  <button onClick={() => setConfirmEnd(false)} style={{ ...pill("#64748b","#64748b","#f8fafc"), cursor:"pointer" }}>No</button>
                </span>
              ) : (
                <button onClick={() => setConfirmEnd(true)} style={{ ...pill("#dc2626","#dc2626","#fef2f2"), cursor:"pointer" }}>End</button>
              )}
            </div>
          </div>
          <div style={{ height:6, background:"#e2e8f0", borderRadius:99, overflow:"hidden" }}>
            <div style={{ height:"100%", background:"#1e3a8a", borderRadius:99, width:`${progress}%`, transition:"width 0.4s" }} />
          </div>
        </div>

        <div className="exam-body">
          <div style={{ marginBottom:20 }}>
            {q.question.split("\n").map((line, i) => {
              const isOpt = /^[a-g]\)|^\d+\./.test(line.trim());
              const m     = isOpt && (line.match(/^([a-g]\))(.*)/) || line.match(/^(\d+\.)(.*)/));
              return (
                <p key={i} style={{ margin:line.trim()===""?"6px 0":"0 0 4px", lineHeight:1.6, fontWeight:isOpt?400:700, fontSize:14 }}>
                  {m ? <><strong>{m[1]}</strong>{m[2]}</> : line}
                </p>
              );
            })}
          </div>

          <div style={{ display:"flex", flexDirection:"column", gap:10, marginBottom:16 }}>
            {OPTS.map(opt => {
              let s = { display:"flex", alignItems:"center", gap:12, padding:"12px 16px", border:"1.5px solid #e2e8f0", borderRadius:10, background:"#f8fafc", cursor:"pointer", textAlign:"left", width:"100%" };
              if (isSub && showAns === "each") {
                if (opt === q.correct)                     s = { ...s, border:"1.5px solid #16a34a", background:"#f0fdf4", cursor:"default" };
                else if (opt === sel && sel !== q.correct) s = { ...s, border:"1.5px solid #dc2626", background:"#fef2f2", cursor:"default" };
              } else if (sel === opt) s = { ...s, border:"1.5px solid #1e3a8a", background:"#eff6ff" };
              return (
                <button key={opt} onClick={() => !isSub && setAnswers(a => ({ ...a, [cur]:opt }))} style={s} disabled={isSub}>
                  <span style={{ fontWeight:700, fontSize:14, color:"#1e3a8a", background:"#dbeafe", borderRadius:6, padding:"2px 8px", minWidth:24, textAlign:"center" }}>{opt}</span>
                  <span style={{ fontSize:14, color:"#1e293b" }}>{q.options[opt]}</span>
                </button>
              );
            })}
          </div>

          {isSub && showAns === "each" && (
            <div style={sel===q.correct
              ? { background:"#f0fdf4", border:"1px solid #16a34a", color:"#15803d", borderRadius:8, padding:"12px 16px", marginBottom:12, fontWeight:600 }
              : { background:"#fef2f2", border:"1px solid #dc2626", color:"#dc2626", borderRadius:8, padding:"12px 16px", marginBottom:12, fontWeight:600 }}>
              {sel===q.correct ? "✅ Correct!" : `❌ Incorrect — the correct answer is ${q.correct}: ${q.options[q.correct]}`}
            </div>
          )}

          {!isSub && (
            <button onClick={() => sel && setSubmitted(s => ({ ...s, [cur]:true }))} disabled={!sel}
              style={sel
                ? { width:"100%", padding:"13px", background:"#1e3a8a", color:"#fff", fontWeight:700, fontSize:15, border:"none", borderRadius:10, cursor:"pointer" }
                : { width:"100%", padding:"13px", background:"#cbd5e1", color:"#94a3b8", fontWeight:700, fontSize:15, border:"none", borderRadius:10, cursor:"not-allowed" }}>
              Submit Answer
            </button>
          )}
        </div>

        <div className="exam-footer">
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:12 }}>
            <button onClick={() => cur > 0 && setCur(c => c-1)} disabled={cur===0}
              style={cur===0
                ? { padding:"9px 18px", borderRadius:8, border:"1.5px solid #e2e8f0", background:"#f8fafc", color:"#cbd5e1", fontWeight:600, fontSize:14, cursor:"not-allowed" }
                : { padding:"9px 18px", borderRadius:8, border:"1.5px solid #1e3a8a", background:"#fff", color:"#1e3a8a", fontWeight:600, fontSize:14, cursor:"pointer" }}>
              ← Previous
            </button>
            {allAnswered
              ? <button onClick={finishExam} style={{ padding:"9px 18px", borderRadius:8, border:"none", background:"#1e3a8a", color:"#fff", fontWeight:700, fontSize:14, cursor:"pointer" }}>See Results →</button>
              : <span style={{ fontSize:13, color:"#94a3b8", fontWeight:500 }}>{Object.keys(submitted).length}/{questions.length} answered</span>}
            <button onClick={() => cur < questions.length-1 && setCur(c => c+1)} disabled={cur===questions.length-1}
              style={cur===questions.length-1
                ? { padding:"9px 18px", borderRadius:8, border:"1.5px solid #e2e8f0", background:"#f8fafc", color:"#cbd5e1", fontWeight:600, fontSize:14, cursor:"not-allowed" }
                : { padding:"9px 18px", borderRadius:8, border:"1.5px solid #1e3a8a", background:"#fff", color:"#1e3a8a", fontWeight:600, fontSize:14, cursor:"pointer" }}>
              Next →
            </button>
          </div>
          <div style={{ display:"flex", flexWrap:"wrap", gap:6, justifyContent:"center" }}>
            {questions.map((_, i) => {
              let bg = "#e2e8f0";
              if (submitted[i]) bg = answers[i]===questions[i].correct ? "#16a34a" : "#dc2626";
              else if (answers[i]) bg = "#93c5fd";
              return <div key={i} onClick={() => setCur(i)}
                style={{ width:12, height:12, borderRadius:"50%", background:bg, cursor:"pointer", outline:i===cur?"2px solid #1e3a8a":"none", outlineOffset:2 }}
                title={`Q${i+1}`} />;
            })}
          </div>
        </div>
      </div></div>
    );
  }

  if (screen === "results") {
    const correct  = Object.entries(submitted).filter(([i]) => answers[i] === questions[i].correct).length;
    const total    = questions.length;
    const answered = Object.keys(submitted).length;
    const pct      = answered > 0 ? correct / total : 0;
    const passed   = pct >= PASS_MARK && !timedOut;

    return (
      <div className="setup-wrap"><div className="setup-card">
        <div style={{ textAlign:"center", marginBottom:24 }}>
          <div style={{ fontSize:52 }}>{timedOut?"⏰":passed?"🏆":"📋"}</div>
          <h2 style={{ fontSize:24, fontWeight:700, color:T.text, marginTop:8 }}>{timedOut?"Time's Up!":passed?"Pass!":"Not Quite"}</h2>
          {timedOut && <p style={{ color:T.amber, fontWeight:600, margin:"4px 0 8px" }}>The exam timer ran out</p>}
          <div style={{ fontSize:40, fontWeight:800, margin:"8px 0 4px", color:passed?T.green:T.red }}>{correct}/{total} — {Math.round(pct*100)}%</div>
          <div style={{ color:T.textMuted, fontSize:14 }}>Pass mark: 65% &nbsp;|&nbsp; {answered} of {total} answered</div>
        </div>
        <div style={{ height:6, background:T.border, borderRadius:99, overflow:"hidden", marginBottom:24 }}>
          <div style={{ height:"100%", background:passed?T.green:T.red, borderRadius:99, width:`${pct*100}%` }} />
        </div>
        <h3 style={{ fontSize:16, fontWeight:700, color:T.text, marginBottom:12 }}>Answer Review</h3>
        {questions.map((q, i) => {
          const s = answers[i]; const ok = s===q.correct;
          return (
            <div key={i} style={s ? (ok
              ? { background:T.greenBg, border:`1px solid ${T.greenBorder}`, borderRadius:8, padding:"12px 14px", marginBottom:10 }
              : { background:T.redBg, border:`1px solid ${T.redBorder}`, borderRadius:8, padding:"12px 14px", marginBottom:10 })
              : { background:T.amberBg, border:`1px solid #78460a`, borderRadius:8, padding:"12px 14px", marginBottom:10 }}>
              <p style={{ margin:"0 0 4px", fontSize:14, color:T.text }}><strong>Q{i+1}:</strong> {q.question.split("\n")[0]}</p>
              {s
                ? <p style={{ margin:"0 0 2px", fontSize:14, color:T.textMuted }}>Your answer: <strong style={{color:T.text}}>{s}: {q.options[s]}</strong></p>
                : <p style={{ margin:"0 0 2px", fontSize:14, color:T.amber }}>Not answered</p>}
              {!ok && <p style={{ margin:0, fontSize:14, color:T.green }}>Correct: <strong>{q.correct}: {q.options[q.correct]}</strong></p>}
            </div>
          );
        })}
        <div style={{ marginTop:24 }}>
          <button onClick={startExam} style={{ width:"100%", padding:"13px", background:"#4a5568", color:"#e2e2e2", fontWeight:700, fontSize:15, border:"none", borderRadius:10, cursor:"pointer" }}>🔄 New Randomised Test</button>
          <button onClick={restart} style={{ width:"100%", padding:"13px", background:T.cardAlt, color:T.accent, fontWeight:700, fontSize:15, border:`1.5px solid ${T.accentBorder}`, borderRadius:10, cursor:"pointer", marginTop:8 }}>⚙️ Change Settings</button>
        </div>
      </div></div>
    );
  }
}